				Type:    "Header",
				Domains: []string{"example.com"},
			},
			wantErr: true,
		},
		{
			name: "cookie auth missing cookies",
			secret: Secret{
				Type:    "Cookie",
				Domains: []string{"example.com"},
			},
			wantErr: true,
		},
		{
			name: "query auth missing params",
			secret: Secret{
				Type:    "Query",
				Domains: []string{"example.com"},
			},
			wantErr: true,
		},
		{
			name: "valid domain regex",
			secret: Secret{
				Type:         "BearerToken",
				DomainsRegex: []string{".*\\.example\\.com"},
				Token:        "abc123",
			},
			wantErr: false,
		},
		{
			name: "invalid domain regex",
			secret: Secret{
				Type:         "BearerToken",
				DomainsRegex: []string{"[invalid"},
				Token:        "abc123",
			},
			wantErr: true,
		},
		{
			name: "case insensitive type",
			secret: Secret{
				Type:    "basicauth",
				Domains: []string{"example.com"},
				Username: "user",
				Password: "pass",
			},
			wantErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.secret.Validate()
			if (err != nil) != tt.wantErr {
				t.Errorf("Secret.Validate() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

