		{
			name:      "with port 443 normalized",
			addr:      "example.com:443",
			wantCount: 1,
		},
		{
			name:      "with port 80 normalized",
			addr:      "example.com:80",
			wantCount: 1,
		},
		{
			name:      "subdomain exact match",
			addr:      "api.example.com",
