)

// HasStdin determines if the user has piped input
func HasStdin() bool {
	stat, err := os.Stdin.Stat()
	if err != nil {
		return false
	}

	mode := stat.Mode()

	isPipedFromChrDev := (mode & os.ModeCharDevice) == 0
	isPipedFromFIFO := (mode & os.ModeNamedPipe) != 0

	return isPipedFromChrDev || isPipedFromFIFO
}

// LoadFile content to slice
func LoadFile(filename string) (lines []string) {
	f, err := os.Open(filename)
	if err != nil {
		return
	}
	defer f.Close() //nolint
	s := bufio.NewScanner(f)
	for s.Scan() {
		lines = append(lines, s.Text())
	}

	return
}

// ListFilesWithPattern in a root folder
func ListFilesWithPattern(rootpattern string) ([]string, error) {
	files, err := filepath.Glob(rootpattern)
	if err != nil {
		return nil, err
	}
	if len(files) == 0 {
		return nil, errors.New("no files found")
	}
	return files, nil
}

// FileNameIsGlob check if the filanem is a pattern
func FileNameIsGlob(pattern string) bool {
	_, err := regexp.Compile(pattern)
	return err == nil
}

func LoadCidrsFromSliceOrFileWithMaxRecursion(option string, splitchar string, maxRecursion int) (networkList []string) {
	if maxRecursion < 0 {
		return
	}
	items := stringz.SplitByCharAndTrimSpace(option, splitchar)
	for _, item := range items {
		if net.ParseIP(item) != nil {
			networkList = append(networkList, item)
		} else if _, _, err := net.ParseCIDR(item); err == nil {
			networkList = append(networkList, item)
		} else if fileutil.FileExists(item) {
			if filedata, err := os.ReadFile(item); err == nil && len(filedata) > 0 {
				networkList = append(networkList, LoadCidrsFromSliceOrFileWithMaxRecursion(string(filedata), "\n", maxRecursion-1)...)
			}
		}
	}

	return
}

func AbsPathOrDefault(p string) string {
	if absPath, err := filepath.Abs(p); err == nil {
		return absPath
	}
	return p
}

package hashes

import (
	"bytes"
	"crypto/md5"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/base64"
	"encoding/hex"
	"fmt"

	"github.com/mfonda/simhash"
	"github.com/spaolacci/murmur3"
)

func stdBase64(braw []byte) []byte {
	bckd := base64.StdEncoding.EncodeToString(braw)
	var buffer bytes.Buffer
	for i := 0; i < len(bckd); i++ {
		ch := bckd[i]
		buffer.WriteByte(ch)
		if (i+1)%76 == 0 {
			buffer.WriteByte('\n')
		}
	}
	buffer.WriteByte('\n')
	return buffer.Bytes()
}

func Mmh3(data []byte) string {
	var h32 = murmur3.New32WithSeed(0)
	h32.Write(stdBase64(data))
	return fmt.Sprintf("%d", int32(h32.Sum32()))
}

func Md5(data []byte) string {
	hash := md5.Sum(data)
	return hex.EncodeToString(hash[:])
}

func Sha1(data []byte) string {
	hash := sha1.Sum(data)
	return hex.EncodeToString(hash[:])
}

func Sha256(data []byte) string {
	hash := sha256.Sum256(data)
	return hex.EncodeToString(hash[:])
}

func Sha224(data []byte) string {
	hash := sha256.Sum224(data)
	return hex.EncodeToString(hash[:])
}

func Sha512(data []byte) string {
	hash := sha512.Sum512(data)
	return hex.EncodeToString(hash[:])
}

func Simhash(data []byte) string {
	hash := simhash.Simhash(simhash.NewWordFeatureSet(data))
	return fmt.Sprintf("%d", hash)
}

package jarm

import (
	"context"
	"fmt"
	"net"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/hdm/jarm-go"
	"github.com/projectdiscovery/fastdialer/fastdialer"
)

const (
	poolCount   = 3
	defaultPort = 443
)

type target struct {
	Host string
	Port int
}

// fingerprint probes a single host/port
func fingerprint(dialer *fastdialer.Dialer, t target, duration int) string {
	results := []string{}
	addr := net.JoinHostPort(t.Host, fmt.Sprintf("%d", t.Port))
	timeout := time.Duration(duration) * time.Second

	ctx, cancel := context.WithTimeout(context.Background(), (time.Duration(duration*poolCount) * time.Second))
	defer cancel()

	pool, err := newOneTimePool(ctx, addr, poolCount)
	if err != nil {
		return ""
	}
	pool.FastDialer = dialer

	defer pool.Close() //nolint
	go pool.Run()      //nolint

	for _, probe := range jarm.GetProbes(t.Host, t.Port) {
		conn, err := pool.Acquire(ctx)
		if err != nil {
			return ""
		}
		if conn == nil {
			return ""
		}
		_ = conn.SetWriteDeadline(time.Now().Add(timeout))
		_, err = conn.Write(jarm.BuildProbe(probe))
		if err != nil {
			_ = conn.Close()
			return ""
		}
		_ = conn.SetReadDeadline(time.Now().Add(timeout))
		buff := make([]byte, 1484)
		_, _ = conn.Read(buff)
		_ = conn.Close()
		ans, err := jarm.ParseServerHello(buff, probe)
		if err != nil {
			return ""
		}
		results = append(results, ans)
	}
	return jarm.RawHashToFuzzyHash(strings.Join(results, ","))
}

func Jarm(dialer *fastdialer.Dialer, host string, duration int) string {
	t := target{}
	if u, err := url.Parse(host); err == nil {
		if u.Scheme == "http" {
			return ""
		}
		t.Host = u.Hostname()
		if portStr := u.Port(); portStr != "" {
			if p, err := strconv.Atoi(portStr); err == nil {
				t.Port = p
			}
		}
	}
	if t.Port == 0 {
		t.Port = defaultPort
	}
	return fingerprint(dialer, t, duration)
}

package jarm

import (
	"context"
	"net"
	"sync"

	"github.com/projectdiscovery/fastdialer/fastdialer"
	"go.uber.org/multierr"
)

// oneTimePool is a pool designed to create continuous bare connections that are for one time only usage
type oneTimePool struct {
	address         string
	idleConnections chan net.Conn
	InFlightConns   *inFlightConns
	ctx             context.Context
	cancel          context.CancelFunc
	FastDialer      *fastdialer.Dialer
}

func newOneTimePool(ctx context.Context, address string, poolSize int) (*oneTimePool, error) {
	idleConnections := make(chan net.Conn, poolSize)
	inFlightConns, err := newInFlightConns()
	if err != nil {
		return nil, err
	}
	pool := &oneTimePool{
		address:         address,
		idleConnections: idleConnections,
		InFlightConns:   inFlightConns,
	}
	if ctx != nil {
		pool.ctx = ctx
	}
	pool.ctx, pool.cancel = context.WithCancel(ctx)
	return pool, nil
}

// Acquire acquires an idle connection from the pool
func (p *oneTimePool) Acquire(c context.Context) (net.Conn, error) {
	select {
	case <-p.ctx.Done():
		return nil, p.ctx.Err()
	case <-c.Done():
		return nil, c.Err()
	case conn := <-p.idleConnections:
		p.InFlightConns.Remove(conn)
		return conn, nil
	}
}

func (p *oneTimePool) Run() error {
	for {
		select {
		case <-p.ctx.Done():
			return p.ctx.Err()
		default:
			var (
				conn net.Conn
				err  error
			)
			if p.FastDialer != nil {
				conn, err = p.FastDialer.Dial(p.ctx, "tcp", p.address)
			} else {
				conn, err = net.Dial("tcp", p.address)
			}
			if err == nil {
				p.InFlightConns.Add(conn)
				p.idleConnections <- conn
			}
		}
	}
}

func (p *oneTimePool) Close() error {
	p.cancel()
	return p.InFlightConns.Close()
}

type inFlightConns struct {
	sync.Mutex
	inflightConns map[net.Conn]struct{}
}

func newInFlightConns() (*inFlightConns, error) {
	return &inFlightConns{inflightConns: make(map[net.Conn]struct{})}, nil
}

func (i *inFlightConns) Add(conn net.Conn) {
	i.Lock()
	defer i.Unlock()

	i.inflightConns[conn] = struct{}{}
}

func (i *inFlightConns) Remove(conn net.Conn) {
	i.Lock()
	defer i.Unlock()

	delete(i.inflightConns, conn)
}

func (i *inFlightConns) Close() error {
	i.Lock()
	defer i.Unlock()

	var errs []error
	for conn := range i.inflightConns {
		if err := conn.Close(); err != nil {
			errs = append(errs, err)
		}
		delete(i.inflightConns, conn)
	}
	return multierr.Combine(errs...)
}

package httputilz

import (
	"bufio"
	"fmt"
	"io"
	"net/http/httputil"
	"strings"

	"github.com/projectdiscovery/retryablehttp-go"
	urlutil "github.com/projectdiscovery/utils/url"
)

const (
	headerParts  = 2
	requestParts = 3
)

// DumpRequest to string
func DumpRequest(req *retryablehttp.Request) (string, error) {
	dump, err := httputil.DumpRequestOut(req.Request, true)

	return string(dump), err
}

// ParseRequest from raw string
func ParseRequest(req string, unsafe bool) (method, path string, headers map[string][]string, body string, err error) {
	headers = make(map[string][]string)
	reader := bufio.NewReader(strings.NewReader(req))
	s, err := reader.ReadString('\n')
	if (err != nil && err != io.EOF) || len(strings.TrimSpace(s)) == 0 {
		if err == nil {
			err = io.EOF
		}
		err = fmt.Errorf("could not read request: %s", err)
		return
	}
	parts := strings.Split(s, " ")
	if len(parts) < requestParts {
		err = fmt.Errorf("malformed request supplied")
		return
	}
	method = parts[0]

	for {
		line, readErr := reader.ReadString('\n')
		line = strings.TrimSpace(line)

		if line == "" {
			break
		}

		// Unsafe skips all checks
		p := strings.SplitN(line, ":", headerParts)
		key := p[0]
		value := ""
		if len(p) == headerParts {
			value = p[1]
		}

		var addHeader bool
		if !unsafe {
			if len(p) == headerParts && !strings.EqualFold(key, "content-length") {
				key = strings.TrimSpace(key)
				value = strings.TrimSpace(value)
				addHeader = true
			}
		} else {
			addHeader = true
		}

		if addHeader {
			headers[key] = append(headers[key], value)
		}

		if readErr != nil {
			break
		}
	}

	// Handle case with the full http url in path. In that case,
	// ignore any host header that we encounter and use the path as request URL
	if strings.HasPrefix(parts[1], "http") {
		var parsed *urlutil.URL
		parsed, err = urlutil.Parse(parts[1])
		if err != nil {
			err = fmt.Errorf("could not parse request URL: %s", err)
			return
		}
		path = parts[1]
		headers["Host"] = []string{parsed.Host}
	} else {
		path = parts[1]
	}

	// Set the request body
	b, err := io.ReadAll(reader)
	if err != nil {
		err = fmt.Errorf("could not read request body: %s", err)
		return
	}
	body = string(b)

	return method, path, headers, body, nil
}

