// helper for IP check test
func isAllNumericParts(d string) bool {
	for _, part := range strings.Split(d, ".") {
		allDigits := true
		for _, c := range part {
			if c < '0' || c > '9' {
				allDigits = false
				break
			}
		}
		if !allDigits {
			return false
		}
	}
	return true
}

