package httpx

import (
	"bytes"
	"io"
	"net/http"
	"strings"

	stringsutil "github.com/projectdiscovery/utils/strings"
	"golang.org/x/net/html/charset"
	"golang.org/x/text/encoding/korean"
	"golang.org/x/text/encoding/simplifiedchinese"
	"golang.org/x/text/encoding/traditionalchinese"
	"golang.org/x/text/transform"
)

// Credits: https://gist.github.com/zhangbaohe/c691e1da5bbdc7f41ca5

// Decodegbk converts GBK to UTF-8
func Decodegbk(s []byte) ([]byte, error) {
	I := bytes.NewReader(s)
	O := transform.NewReader(I, simplifiedchinese.GBK.NewDecoder())
	d, e := io.ReadAll(O)
	if e != nil {
		return nil, e
	}
	return d, nil
}

// Decodebig5 converts BIG5 to UTF-8
func Decodebig5(s []byte) ([]byte, error) {
	I := bytes.NewReader(s)
	O := transform.NewReader(I, traditionalchinese.Big5.NewDecoder())
	d, e := io.ReadAll(O)
	if e != nil {
		return nil, e
	}
	return d, nil
}

// Encodebig5 converts UTF-8 to BIG5
func Encodebig5(s []byte) ([]byte, error) {
	I := bytes.NewReader(s)
	O := transform.NewReader(I, traditionalchinese.Big5.NewEncoder())
	d, e := io.ReadAll(O)
	if e != nil {
		return nil, e
	}
	return d, nil
}

func DecodeKorean(s []byte) ([]byte, error) {
	koreanDecoder := korean.EUCKR.NewDecoder()
	return koreanDecoder.Bytes(s)
}

// charsetParamIs reports whether contentType declares exactly this charset.
// contentType is already lowercased and unquoted.
func charsetParamIs(contentType, charset string) bool {
	for _, param := range strings.Split(contentType, ";") {
		name, value, found := strings.Cut(strings.TrimSpace(param), "=")
		if found && strings.TrimSpace(name) == "charset" && strings.TrimSpace(value) == charset {
			return true
		}
	}
	return false
}

// charsetParam returns the value of the charset parameter of contentType, or
// an empty string. contentType is already lowercased and unquoted.
func charsetParam(contentType string) string {
	for _, param := range strings.Split(contentType, ";") {
		name, value, found := strings.Cut(strings.TrimSpace(param), "=")
		if found && strings.TrimSpace(name) == "charset" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

// decodeCharset converts data from the charset named by label to UTF-8. Data
// is returned as is when the label is empty, names UTF-8 or is not known.
func decodeCharset(data []byte, label string) ([]byte, error) {
	if label == "" {
		return data, nil
	}
	encoding, name := charset.Lookup(label)
	if encoding == nil || name == "utf-8" {
		return data, nil
	}
	return encoding.NewDecoder().Bytes(data)
}

// DecodeData converts a response body that is not UTF-8 to UTF-8, using the
// charset declared in the Content-Type header or in the page itself.
func DecodeData(data []byte, headers http.Header) ([]byte, error) {
	// A charset named by the header wins over the page. An unknown label, or
	// no Content-Type at all, falls through to the page.
	headerCharsetKnown := false
	if contentTypes, ok := headers["Content-Type"]; ok {
		contentType := strings.ToLower(strings.Join(contentTypes, ";"))
		// the charset parameter value can be a quoted string (charset="gbk")
		contentType = strings.NewReplacer(`"`, "", `'`, "").Replace(contentType)

		switch {
		case stringsutil.ContainsAny(contentType, "charset=gb2312", "charset=gbk"):
			return Decodegbk([]byte(data))
		case stringsutil.ContainsAny(contentType, "euc-kr"):
			return DecodeKorean(data)
		case charsetParamIs(contentType, "big5"):
			return Decodebig5(data)
		}

		// Any other charset declared in the header, such as iso-8859-1. A label
		// that is not a charset is ignored, and the page is looked at instead.
		if label := charsetParam(contentType); label != "" {
			if encoding, name := charset.Lookup(label); encoding != nil {
				headerCharsetKnown = true
				if name != "utf-8" {
					return encoding.NewDecoder().Bytes(data)
				}
			}
		}
	}
	if headerCharsetKnown {
		return data, nil
	}

	// Charset declared in a meta tag. This runs when the header is missing too.
	var match = reContentType.FindSubmatch(data)
	var mcontentType = ""
	if len(match) != 0 {
		for i, v := range match {
			if string(v) != "" && i != 0 {
				mcontentType = string(v)
			}
		}
		mcontentType = strings.ToLower(mcontentType)
	}
	switch {
	case stringsutil.ContainsAny(mcontentType, "gb2312", "gbk"):
		return Decodegbk(data)
	case stringsutil.ContainsAny(mcontentType, "big5", "Big5"):
		return Decodebig5(data)
	}
	return decodeCharset(data, mcontentType)
}

package httpx

import (
	"net/http"
	"testing"

	"github.com/stretchr/testify/require"
	"golang.org/x/text/encoding/japanese"
	"golang.org/x/text/encoding/simplifiedchinese"
)

func TestDecodeDataDeclaredCharset(t *testing.T) {
	shiftJIS, err := japanese.ShiftJIS.NewEncoder().Bytes([]byte("<title>日本語</title>"))
	require.NoError(t, err)
	gbk, err := simplifiedchinese.GBK.NewEncoder().Bytes([]byte("<title>中文</title>"))
	require.NoError(t, err)

	tests := []struct {
		name        string
		contentType string
		body        []byte
		want        string
	}{
		{
			name:        "iso-8859-1 in the Content-Type header",
			contentType: "text/html; charset=iso-8859-1",
			body:        []byte("<title>caf\xe9</title>"),
			want:        "<title>café</title>",
		},
		{
			name:        "windows-1252 in the Content-Type header",
			contentType: "text/html; charset=windows-1252",
			body:        []byte("<title>price \x80 5</title>"),
			want:        "<title>price € 5</title>",
		},
		{
			name:        "quoted charset and upper case",
			contentType: `text/html; charset="ISO-8859-1"`,
			body:        []byte("<title>na\xefve</title>"),
			want:        "<title>naïve</title>",
		},
		{
			name:        "shift_jis in the Content-Type header",
			contentType: "text/html; charset=shift_jis",
			body:        shiftJIS,
			want:        "<title>日本語</title>",
		},
		{
			name:        "charset only in a meta tag",
			contentType: "text/html",
			body:        []byte(`<meta charset="iso-8859-1"><title>caf` + "\xe9" + `</title>`),
			want:        `<meta charset="iso-8859-1"><title>café</title>`,
		},
		{
			name: "charset only in a meta tag and no Content-Type",
			body: []byte(`<meta charset="iso-8859-1"><title>caf` + "\xe9" + `</title>`),
			want: `<meta charset="iso-8859-1"><title>café</title>`,
		},
		{
			name:        "single quoted charset in the Content-Type header",
			contentType: "text/html; charset='iso-8859-1'",
			body:        []byte("<title>caf\xe9</title>"),
			want:        "<title>café</title>",
		},
		{
			name:        "unquoted charset in a meta tag",
			contentType: "text/html",
			body:        []byte(`<meta charset=iso-8859-1><title>caf` + "\xe9" + `</title>`),
			want:        `<meta charset=iso-8859-1><title>café</title>`,
		},
		{
			name:        "an unknown header charset falls back to the page",
			contentType: "text/html; charset=not-a-charset",
			body:        append([]byte(`<meta charset="iso-8859-1"><title>caf`), []byte("\xe9</title>")...),
			want:        `<meta charset="iso-8859-1"><title>café</title>`,
		},
		{
			name:        "the header wins over the page",
			contentType: "text/html; charset=utf-8",
			body:        []byte(`<meta charset="iso-8859-1"><title>café</title>`),
			want:        `<meta charset="iso-8859-1"><title>café</title>`,
		},
		{
			name:        "charset text outside a meta tag is ignored",
			contentType: "text/html",
			body:        []byte(`<script>var s = "charset=utf-8";</script><meta charset="iso-8859-1"><title>caf` + "\xe9" + `</title>`),
			want:        `<script>var s = "charset=utf-8";</script><meta charset="iso-8859-1"><title>café</title>`,
		},
		{
			name:        "charset in a meta http-equiv tag",
			contentType: "text/html",
			body:        []byte(`<meta http-equiv="Content-Type" content="text/html; charset=iso-8859-1"><title>caf` + "\xe9" + `</title>`),
			want:        `<meta http-equiv="Content-Type" content="text/html; charset=iso-8859-1"><title>café</title>`,
		},
		{
			name:        "gbk is still decoded",
			contentType: "text/html; charset=gbk",
			body:        gbk,
			want:        "<title>中文</title>",
		},
		{
			name:        "utf-8 is left alone",
			contentType: "text/html; charset=utf-8",
			body:        []byte("<title>café 日本語</title>"),
			want:        "<title>café 日本語</title>",
		},
		{
			name:        "no charset is left alone",
			contentType: "text/html",
			body:        []byte("<title>caf\xe9</title>"),
			want:        "<title>caf\xe9</title>",
		},
		{
			name:        "unknown charset is left alone",
			contentType: "text/html; charset=not-a-charset",
			body:        []byte("<title>caf\xe9</title>"),
			want:        "<title>caf\xe9</title>",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			headers := http.Header{}
			if tt.contentType != "" {
				headers.Set("Content-Type", tt.contentType)
			}
			got, err := DecodeData(tt.body, headers)
			require.NoError(t, err)
			require.Equal(t, tt.want, string(got))
		})
	}
}

func TestExtractTitleDeclaredCharset(t *testing.T) {
	headers := http.Header{"Content-Type": []string{"text/html; charset=iso-8859-1"}}
	data, err := DecodeData([]byte("<html><head><title>caf\xe9</title></head></html>"), headers)
	require.NoError(t, err)

	require.Equal(t, "café", ExtractTitle(&Response{Data: data, Raw: string(data)}))
}

package httpx

import (
	"regexp"

	stringsutil "github.com/projectdiscovery/utils/strings"
)

// Filter defines a generic filter interface to apply to responses
type Filter interface {
	Filter(response *Response) (bool, error)
}

// FilterString defines a filter of type string
type FilterString struct {
	Keywords []string
}

// Filter a response with strings filtering
func (f FilterString) Filter(response *Response) (bool, error) {
	return stringsutil.ContainsAnyI(response.Raw, f.Keywords...), nil
}

// FilterRegex defines a filter of type regex
type FilterRegex struct {
	Regexs []string
}

// Filter a response with regexes
func (f FilterRegex) Filter(response *Response) (bool, error) {
	for _, regex := range f.Regexs {
		matched, err := regexp.MatchString(regex, response.Raw)
		if err != nil {
			return false, err
		}
		if matched {
			return true, nil
		}
	}

	return false, nil
}

// CustomCallback used in custom filters
type CustomCallback func(response *Response) (bool, error)

// FilterCustom defines a filter with callback functions applied
type FilterCustom struct {
	CallBacks []CustomCallback
}

// Filter a response with custom callbacks
func (f FilterCustom) Filter(response *Response) (bool, error) {
	for _, callback := range f.CallBacks {
		ok, err := callback(response)
		if err != nil {
			return false, err
		}
		if ok {
			return true, nil
		}
	}

	return false, nil
}

package httpx

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestFilterCustomErrorPropagation(t *testing.T) {
	t.Run("error from callback is returned, not swallowed", func(t *testing.T) {
		expectedErr := errors.New("callback failure")
		callback := func(response *Response) (bool, error) {
			return true, expectedErr
		}
		filter := FilterCustom{CallBacks: []CustomCallback{callback}}
		ok, err := filter.Filter(&Response{})
		require.False(t, ok, "ok should be false when callback returns an error")
		require.ErrorIs(t, err, expectedErr, "error from callback should be propagated")
	})

	t.Run("error from callback with ok=false is returned", func(t *testing.T) {
		expectedErr := errors.New("callback failure")
		callback := func(response *Response) (bool, error) {
			return false, expectedErr
		}
		filter := FilterCustom{CallBacks: []CustomCallback{callback}}
		ok, err := filter.Filter(&Response{})
		require.False(t, ok)
		require.ErrorIs(t, err, expectedErr)
	})

	t.Run("first matching callback without error returns true", func(t *testing.T) {
		callbacks := []CustomCallback{
			func(response *Response) (bool, error) { return false, nil },
			func(response *Response) (bool, error) { return true, nil },
			func(response *Response) (bool, error) { return true, nil },
		}
		filter := FilterCustom{CallBacks: callbacks}
		ok, err := filter.Filter(&Response{})
		require.True(t, ok)
		require.NoError(t, err)
	})

	t.Run("error stops remaining callbacks", func(t *testing.T) {
		called := 0
		filter := FilterCustom{CallBacks: []CustomCallback{
			func(*Response) (bool, error) {
				called++
				return false, errors.New("fail")
			},
			func(*Response) (bool, error) {
				called++
				return true, nil
			},
		}}
		ok, err := filter.Filter(&Response{})
		require.False(t, ok)
		require.Error(t, err)
		require.Equal(t, 1, called)
	})

	t.Run("no callbacks match returns false with nil error", func(t *testing.T) {
		callbacks := []CustomCallback{
			func(response *Response) (bool, error) { return false, nil },
			func(response *Response) (bool, error) { return false, nil },
		}
		filter := FilterCustom{CallBacks: callbacks}
		ok, err := filter.Filter(&Response{})
		require.False(t, ok)
		require.NoError(t, err)
	})
}

package httpx

import (
	"context"
	"fmt"
	"io"
	"net/http"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/retryablehttp-go"
)

const (
	// HTTP defines the plain http scheme
	HTTP = "http"
	// HTTPS defines the secure http scheme
	HTTPS = "https"
	// HTTPorHTTPS defines both http and https scheme in mutual exclusion
	HTTPorHTTPS = "http|https"
	// HTTPandHTTPS defines both http and https scheme
	HTTPandHTTPS = "http&https"
)

// SupportHTTP2 checks if the target host supports HTTP2
func (h *HTTPX) SupportHTTP2(protocol, method, targetURL string) bool {
	// http => supports HTTP1.1 => HTTP/2 (H2C)
	if protocol == HTTP {
		req, err := retryablehttp.NewRequest(method, targetURL, nil)
		if err != nil {
			return false
		}
		req.Header.Set("Connection", "Upgrade, HTTP2-Settings")
		req.Header.Set("Upgrade", "h2c")
		req.Header.Set("HTTP2-Settings", "AAMAAABkAARAAAAAAAIAAAAA")
		httpresp, err := h.client.Do(req)
		if err != nil {
			return false
		}

		err = freeHTTPResources(httpresp)
		if err != nil {
			gologger.Error().Msgf("%s", err)
			return false
		}

		return httpresp.StatusCode == http.StatusSwitchingProtocols
	}

	// attempts a direct http2 connection
	req, err := http.NewRequestWithContext(context.Background(), method, targetURL, nil)
	if err != nil {
		return false
	}

	httpresp, err := h.client2.Do(req)
	if err != nil {
		return false
	}

	err = freeHTTPResources(httpresp)
	if err != nil {
		gologger.Error().Msgf("%s", err)
		return false
	}

	return httpresp.Proto == "HTTP/2.0"
}

func freeHTTPResources(response *http.Response) error {
	_, err := io.Copy(io.Discard, response.Body)
	if err != nil {
		return fmt.Errorf("could not discard response body: %s", err)
	}

	err = response.Body.Close()
	if err != nil {
		return fmt.Errorf("could not close response body: %s", err)
	}

	return nil
}

package httpx

import (
	"bytes"
	"context"
	"crypto/tls"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/textproto"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/microcosm-cc/bluemonday"
	"github.com/projectdiscovery/cdncheck"
	"github.com/projectdiscovery/fastdialer/fastdialer"
	"github.com/projectdiscovery/fastdialer/fastdialer/ja3"
	"github.com/projectdiscovery/fastdialer/fastdialer/ja3/impersonate"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/httpx/common/httputilz"
	"github.com/projectdiscovery/networkpolicy"
	"github.com/projectdiscovery/rawhttp"
	retryablehttp "github.com/projectdiscovery/retryablehttp-go"
