// DefaultMaxResponseBodySize is the default maximum response body size that httpx
// reads into memory for processing (and, via the runner, the default cap for
// responses stored to disk with -sr). It is intentionally bounded: the body is
// held in memory and the footprint scales with the number of concurrent threads,
// so a very large cap can lead to excessive memory usage / OOM on large
// responses. Normal web pages are far smaller than this; use -rstr / -rsts to
// read or store larger responses when needed.
//
// NOTE: this is a var initializer (not an init() function) on purpose. init()
// functions run after all package-level variable initializers, so computing the
// value in init() left DefaultOptions (which references it below) observing a
// zero value during package initialization.
var DefaultMaxResponseBodySize = func() int64 {
	maxResponseBodySize, _ := humanize.ParseBytes("50mb")
	return int64(maxResponseBodySize)
}()

// Options contains configuration options for the client
type Options struct {
	RandomAgent      bool
	AutoReferer      bool
	DefaultUserAgent string
	Proxy            string
	// Deprecated: use Proxy
	HTTPProxy string
	// Deprecated: use Proxy
	SocksProxy  string
	Threads     int
	CdnCheck    string
	ExcludeCdn  bool
	ExtractFqdn bool
	// ExtractCSP extracts the domains of the Content-Security-Policy
	ExtractCSP bool
	// Timeout is the maximum time to wait for the request
	Timeout time.Duration
	// RetryMax is the maximum number of retries
	RetryMax      int
	CustomHeaders map[string][]string
	// VHostSimilarityRatio 1 - 100
	VHostSimilarityRatio int
	FollowRedirects      bool
	FollowHostRedirects  bool
	RespectHSTS          bool
	MaxRedirects         int
	Unsafe               bool
	TLSGrab              bool
	ZTLS                 bool
	// VHOSTs options
	VHostIgnoreStatusCode     bool
	VHostIgnoreContentLength  bool
	VHostIgnoreNumberOfWords  bool
	VHostIgnoreNumberOfLines  bool
	VHostStripHTML            bool
	MaxResponseBodySizeToSave int64
	MaxResponseBodySizeToRead int64
	UnsafeURI                 string
	Resolvers                 []string
	customCookies             []*http.Cookie
	SniName                   string
	TlsImpersonate            string
	NetworkPolicy             *networkpolicy.NetworkPolicy
	CDNCheckClient            *cdncheck.Client
	Protocol                  Proto
	Trace                     bool
	AuthProvider              authprovider.AuthProvider
}

// DefaultOptions contains the default options
var DefaultOptions = Options{
	RandomAgent:               true,
	Threads:                   25,
	Timeout:                   30 * time.Second,
	RetryMax:                  5,
	MaxRedirects:              10,
	Unsafe:                    false,
	CdnCheck:                  "true",
	ExcludeCdn:                false,
	MaxResponseBodySizeToRead: DefaultMaxResponseBodySize,
	// VHOSTs options
	VHostIgnoreStatusCode:    false,
	VHostIgnoreContentLength: true,
	VHostIgnoreNumberOfWords: false,
	VHostIgnoreNumberOfLines: false,
	VHostStripHTML:           false,
	VHostSimilarityRatio:     85,
	DefaultUserAgent:         "httpx - Open-source project (github.com/projectdiscovery/httpx)",
}

func (options *Options) parseCustomCookies() {
	// parse and fill the custom field
	for k, v := range options.CustomHeaders {
		if strings.EqualFold(k, "cookie") {
			req := http.Request{Header: http.Header{"Cookie": v}}
			options.customCookies = req.Cookies()
		}
	}
}

func (options *Options) hasCustomCookies() bool {
	return len(options.customCookies) > 0
}

package httpx

import (
	"crypto/tls"
	"fmt"
	"net"
	"strings"
	"time"

	stringsutil "github.com/projectdiscovery/utils/strings"
)

// SupportPipeline checks if the target host supports HTTP1.1 pipelining by sending x probes
// and reading back responses expecting at least 2 with HTTP/1.1 or HTTP/1.0
func (h *HTTPX) SupportPipeline(protocol, method, host string, port int) bool {
	addr := host
	if port == 0 {
		port = 80
		if protocol == "https" {
			port = 443
		}
	}
	if _, _, err := net.SplitHostPort(host); err != nil && port > 0 {
		addr = fmt.Sprintf("%s:%d", host, port)
	}
	// dummy method while awaiting for full rawhttp implementation
	dummyReq := fmt.Sprintf("%s / HTTP/1.1\nHost: %s\n\n", method, addr)
	conn, err := pipelineDial(protocol, addr)
	if err != nil {
		return false
	}
	defer func() { _ = conn.Close() }()
	// send some probes
	nprobes := 10
	for i := 0; i < nprobes; i++ {
		if _, err = conn.Write([]byte(dummyReq)); err != nil {
			return false
		}
	}
	gotReplies := 0
	reply := make([]byte, 1024)
	for i := 0; i < nprobes; i++ {
		err := conn.SetReadDeadline(time.Now().Add(1 * time.Second))
		if err != nil {
			return false
		}

		if _, err := conn.Read(reply); err != nil {
			break
		}

		// The check is very naive, but it works most of the times
		for _, s := range strings.Split(string(reply), "\n\n") {
			if stringsutil.ContainsAnyI(s, "HTTP/1.1", "HTTP/1.0") {
				gotReplies++
			}
		}
	}

	// expect at least 2 replies
	return gotReplies >= 2 //nolint
}

func pipelineDial(protocol, addr string) (net.Conn, error) {
	// http
	if protocol == "http" {
		return net.Dial("tcp", addr)
	}

	// https
	return tls.Dial("tcp", addr, &tls.Config{InsecureSkipVerify: true})
}

package httpx

import (
	"io"
	"net"
	"strconv"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestSupportPipelineClosesConn(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	defer func() { _ = ln.Close() }()

	_, portStr, err := net.SplitHostPort(ln.Addr().String())
	require.NoError(t, err)
	port, err := strconv.Atoi(portStr)
	require.NoError(t, err)

	closed := make(chan struct{})
	go func() {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		defer func() { _ = conn.Close() }()
		buf := make([]byte, 64*1024)
		_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
		_, _ = conn.Read(buf)
		_, _ = conn.Write([]byte("HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\nHTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n"))
		_, _ = io.Copy(io.Discard, conn)
		close(closed)
	}()

	h := &HTTPX{}
	_ = h.SupportPipeline("http", "GET", "127.0.0.1", port)

	select {
	case <-closed:
	case <-time.After(3 * time.Second):
		t.Fatal("pipeline probe connection was not closed")
	}
}

func TestSupportPipelineDialError(t *testing.T) {
	h := &HTTPX{}
	require.False(t, h.SupportPipeline("http", "GET", "127.0.0.1", 1))
}

