	"sync"

	"github.com/projectdiscovery/fastdialer/fastdialer"
	"golang.org/x/net/idna"
)

// ErrPinnedThroughProxy is the error of a request to a pinned host that would
// go through a proxy, which resolves the host itself.
var ErrPinnedThroughProxy = errors.New("a host pinned to an ip cannot be reached through a proxy")

// requestHost is the host a request is made to: the ip it is pinned to, if
// any, and the ip of the last connection dialed to it.
type requestHost struct {
	name   string
	pinned string
	mu     sync.Mutex
	dialed string
}

// requestHostKey is the context key of the requestHost of WithHost.
type requestHostKey struct{}

// WithHost returns a copy of ctx for requests to host. When ip is set, they
// connect to it, like curl --resolve but on every port of host, while the host
// keeps its name for the Host header and SNI. The ip they are dialed to is
// recorded for DialedIP, while the dialer only keeps the last ip dialed to a
// host by any request. Requests to other hosts, such as redirect targets, are
// resolved as usual and not recorded.
func WithHost(ctx context.Context, host, ip string) context.Context {
	host = canonicalHost(host)
	if ip != "" {
		ctx = fastdialer.WithResolveOverride(ctx, host, ip)
	}
	return context.WithValue(ctx, requestHostKey{}, &requestHost{name: host, pinned: ip})
}

// PinnedContext returns a new context for another request derived from req,
// in which the host of req keeps the ip it is pinned to. The other values of
// the context of req, such as a trace, are not kept.
func PinnedContext(req *http.Request) context.Context {
	return WithHost(context.Background(), req.URL.Hostname(), pinnedIP(req))
}

// DialedIP returns the ip of the last connection dialed to the host of a
// WithHost context, or "" if none was.
func DialedIP(ctx context.Context) string {
	host, ok := ctx.Value(requestHostKey{}).(*requestHost)
	if !ok {
		return ""
	}
	host.mu.Lock()
	defer host.mu.Unlock()
	return host.dialed
}

// hostOf returns the requestHost of ctx if name, however it is spelled, is its
// host, and nil otherwise.
func hostOf(ctx context.Context, name string) *requestHost {
	host, ok := ctx.Value(requestHostKey{}).(*requestHost)
	if !ok || host.name != canonicalHost(name) {
		return nil
	}
	return host
}

// pinnedIP returns the ip the host of req is pinned to in its context, if any.
func pinnedIP(req *http.Request) string {
	if host := hostOf(req.Context(), req.URL.Hostname()); host != nil {
		return host.pinned
	}
	return ""
}

// canonicalHost folds the case, the IDNA form and a trailing dot of host, as
// fastdialer keys its resolve overrides, so that a host matches the requests
// and dials to it however it is spelled.
func canonicalHost(host string) string {
	if ascii, err := idna.Lookup.ToASCII(host); err == nil {
		host = ascii
	}
	return strings.TrimSuffix(strings.ToLower(host), ".")
}

// refusePinned wraps the proxy of a transport so that a request to a pinned
// host fails instead of going through the proxy.
func refusePinned(proxy func(*http.Request) (*url.URL, error)) func(*http.Request) (*url.URL, error) {
	return func(req *http.Request) (*url.URL, error) {
		proxyURL, err := proxy(req)
		if proxyURL != nil && pinnedIP(req) != "" {
			return nil, ErrPinnedThroughProxy
		}
		return proxyURL, err
	}
}

// dialFunc dials addr, as net.Dialer.DialContext does.
type dialFunc func(ctx context.Context, network, addr string) (net.Conn, error)

// recordDialedIP wraps dial to record the ip of a connection to the host of a
// WithHost context. A connection to another host, such as a proxy, is not
// recorded.
func recordDialedIP(dial dialFunc) dialFunc {
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		conn, err := dial(ctx, network, addr)
		if err != nil {
			return conn, err
		}
		name, _, _ := net.SplitHostPort(addr)
		if host := hostOf(ctx, name); host != nil {
			ip, _, _ := net.SplitHostPort(conn.RemoteAddr().String())
			host.mu.Lock()
			host.dialed = ip
			host.mu.Unlock()
		}
		return conn, nil
	}
}

package httpx

import (
	"context"
	"net"
	"net/http"
	"net/http/httptrace"
	"net/url"
	"os"
	"os/exec"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestRefusePinned(t *testing.T) {
	proxyURL, err := url.Parse("http://127.0.0.1:3128")
	require.NoError(t, err)
	proxy := refusePinned(http.ProxyURL(proxyURL))
	request := func(ctx context.Context, rawURL string) *http.Request {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
		require.NoError(t, err)
		return req
	}

	// a pinned host however it is spelled
	for host, rawURL := range map[string]string{"Pinned.Test.": "https://PINNED.test.:8443/", "xn--bcher-kva.test": "https://bücher.test/"} {
		_, err = proxy(request(WithHost(context.Background(), host, "192.0.2.10"), rawURL))
		require.ErrorIs(t, err, ErrPinnedThroughProxy, rawURL)
	}

	pinned := WithHost(context.Background(), "pinned.test", "192.0.2.10")
	got, err := proxy(request(pinned, "https://other.test/"))
	require.NoError(t, err)
	require.Equal(t, proxyURL, got, "a request to another host, as a redirect, keeps the proxy")

	got, err = proxy(request(WithHost(context.Background(), "plain.test", ""), "https://plain.test/"))
	require.NoError(t, err)
	require.Equal(t, proxyURL, got, "a host that is not pinned keeps the proxy")

	got, err = refusePinned(http.ProxyURL(nil))(request(pinned, "https://pinned.test/"))
	require.NoError(t, err)
	require.Nil(t, got, "a pinned request without a proxy")
}

// A proxy set in the environment is refused for a pinned request as well. Go
// reads the proxies of the environment once, so the test runs in a new process.
func TestRefusePinned_environment(t *testing.T) {
	if os.Getenv("HTTPX_TEST_ENV_PROXY") == "" {
		cmd := exec.Command(os.Args[0], "-test.run=^TestRefusePinned_environment$")
		// the lower case names first: on Windows, the last of two spellings wins
		cmd.Env = append(os.Environ(), "HTTPX_TEST_ENV_PROXY=1", "http_proxy=", "no_proxy=", "NO_PROXY=", "HTTP_PROXY=http://127.0.0.1:1")
		output, err := cmd.CombinedOutput()
		require.NoError(t, err, string(output))
		return
	}

	options := DefaultOptions
	options.RetryMax = 0
	h, err := New(&options)
	require.NoError(t, err)
	req, err := h.NewRequestWithContext(WithHost(context.Background(), "pinned.test", "127.0.0.1"), http.MethodGet, "http://pinned.test/")
	require.NoError(t, err)
	_, err = h.Do(req, UnsafeOptions{})
	require.ErrorIs(t, err, ErrPinnedThroughProxy)
}

func TestCanonicalHost(t *testing.T) {
	for host, want := range map[string]string{
		"Pinned.Test.":       "pinned.test",
		"bücher.test":        "xn--bcher-kva.test",
		"BÜCHER.test":        "xn--bcher-kva.test",
		"bücher。test":        "xn--bcher-kva.test",
		"xn--bcher-kva.test": "xn--bcher-kva.test",
	} {
		require.Equal(t, want, canonicalHost(host), host)
	}
}

func TestPinnedContext(t *testing.T) {
	ctx := httptrace.WithClientTrace(WithHost(context.Background(), "pinned.test", "192.0.2.10"), &httptrace.ClientTrace{})
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, "https://pinned.test/favicon.ico", nil)
	require.NoError(t, err)

	derived := req.Clone(PinnedContext(req))
	require.Equal(t, "192.0.2.10", pinnedIP(derived), "the pin is kept")
	require.Nil(t, httptrace.ContextClientTrace(derived.Context()), "the trace is not")

	other, err := http.NewRequest(http.MethodGet, "https://other.test/", nil)
	require.NoError(t, err)
	require.Empty(t, pinnedIP(other.Clone(PinnedContext(other))))
}

func TestRecordDialedIP(t *testing.T) {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	defer func() { _ = listener.Close() }()
	// every address is dialed to the listener
	dial := recordDialedIP(func(ctx context.Context, network, _ string) (net.Conn, error) {
		return (&net.Dialer{}).DialContext(ctx, network, listener.Addr().String())
	})
	ctx := WithHost(context.Background(), "dialed.test", "")

	conn, err := dial(ctx, "tcp", "proxy.test:3128")
	require.NoError(t, err)
	_ = conn.Close()
	require.Empty(t, DialedIP(ctx), "a dial to another host, such as a proxy")

	// net/http dials a host as it is spelled
	conn, err = dial(ctx, "tcp", "DIALED.test.:80")
	require.NoError(t, err)
	_ = conn.Close()
	require.Equal(t, "127.0.0.1", DialedIP(ctx))
}

package httpx

import (
	"strings"
	"time"

	"github.com/projectdiscovery/tlsx/pkg/tlsx/clients"
	httputil "github.com/projectdiscovery/utils/http"
)

// Response contains the response to a server
type Response struct {
	Input         string // input that was given
	StatusCode    int
	Headers       map[string][]string
	RawData       []byte // undecoded data
	Data          []byte // decoded data
	ContentLength int
	Raw           string
	RawHeaders    string
	Words         int
	Lines         int
	TLSData       *clients.Response
	CSPData       *CSPData
	BodyDomains   *BodyDomain
	HTTP2         bool
	Pipeline      bool
	Duration      time.Duration
	Chain         []httputil.ChainItem
}

// ChainItem request=>response
type ChainItem struct {
	Request    string `json:"request,omitempty"`
	Response   string `json:"response,omitempty"`
	StatusCode int    `json:"status_code,omitempty"`
	Location   string `json:"location,omitempty"`
	RequestURL string `json:"request-url,omitempty"`
}

// GetHeader value
func (r *Response) GetHeader(name string) string {
	v, ok := r.Headers[name]
	if ok {
		return strings.Join(v, " ")
	}
	return ""
}

// GetHeaderPart with offset
func (r *Response) GetHeaderPart(name, sep string) string {
	v, ok := r.Headers[name]
	if ok && len(v) > 0 {
		tokens := strings.Split(strings.Join(v, " "), sep)
		return tokens[0]
	}

	return ""
}

// GetChainStatusCodes from redirects
func (r *Response) GetChainStatusCodes() []int {
	var statusCodes []int
	for _, chainItem := range r.Chain {
		statusCodes = append(statusCodes, chainItem.StatusCode)
	}
	return statusCodes
}

// GetChain dump the whole redirect chain as string
func (r *Response) GetChain() string {
	var respchain strings.Builder
	for counter, chainItem := range r.Chain {
		if counter != 0 {
			respchain.Write(chainItem.Request)
		}
		if counter < len(r.Chain)-1 {
			respchain.Write(chainItem.Response)
		}
	}
	return respchain.String()
}

// GetChainAsSlice dump the whole redirect chain as structuerd slice
func (r *Response) GetChainAsSlice() (chain []ChainItem) {
	for _, chainItem := range r.Chain {
		chain = append(chain, ChainItem{
			Request:    string(chainItem.Request),
			Response:   string(chainItem.Response),
			StatusCode: chainItem.StatusCode,
			Location:   chainItem.Location,
			RequestURL: chainItem.RequestURL,
		})
	}
	return
}

// HasChain redirects
func (r *Response) HasChain() bool {
	return len(r.Chain) > 1
}

// GetChainLastURL returns the final URL
func (r *Response) GetChainLastURL() string {
	if r.HasChain() {
		lastitem := r.Chain[len(r.Chain)-1]
		return lastitem.RequestURL
	}
	return ""
}

package httpx

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/stretchr/testify/require"
	"golang.org/x/text/encoding/simplifiedchinese"
	"golang.org/x/text/transform"
)

// newLocalHTTPX builds an HTTPX instance suitable for hitting a local test
// server only (no external network, CDN checks disabled).
func newLocalHTTPX(t *testing.T) *HTTPX {
	t.Helper()
	options := DefaultOptions
	options.CdnCheck = "false"
	options.Timeout = 5 * time.Second
	options.RetryMax = 0
	// NB: relies on DefaultOptions.MaxResponseBodySizeToRead being non-zero
	// (see TestDefaultOptionsHasNonZeroReadSize) so the body is actually read.

	ht, err := New(&options)
	require.NoError(t, err)
	return ht
}

// doLocal issues a GET against a local httptest server and returns the parsed
// httpx Response.
func doLocal(t *testing.T, ht *HTTPX, url string) *Response {
	t.Helper()
	req, err := retryablehttp.NewRequest(http.MethodGet, url, nil)
	require.NoError(t, err)
	resp, err := ht.Do(req, UnsafeOptions{})
	require.NoError(t, err)
	return resp
}

// legacyWordsLines reproduces the exact word/line computation that existed
// before the refactor, so we can assert the new byte-based path is equivalent.
func legacyWordsLines(body []byte) (words, lines int) {
	s := string(body)
	if s != "" {
		words = len(strings.Split(s, " "))
		lines = len(strings.Split(strings.TrimSpace(s), "\n"))
	}
	return
}

// TestDefaultOptionsHasNonZeroReadSize guards against the package var-init
// ordering regression where DefaultOptions was initialized before
// DefaultMaxResponseBodySize, leaving MaxResponseBodySizeToRead at 0 (which made
// LimitReader read zero bytes and produced empty bodies for library users).
func TestDefaultOptionsHasNonZeroReadSize(t *testing.T) {
	require.NotZero(t, DefaultMaxResponseBodySize)
	require.Equal(t, DefaultMaxResponseBodySize, DefaultOptions.MaxResponseBodySizeToRead)
}

func TestDoBodyNoDecodePreservesRawAndData(t *testing.T) {
	body := []byte("hello world\nsecond line\n")
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write(body)
	}))
	defer ts.Close()

	resp := doLocal(t, newLocalHTTPX(t), ts.URL)

	require.Equal(t, body, resp.Data, "decoded data must equal body")
	require.Equal(t, body, resp.RawData, "raw data must equal undecoded body")

	wantWords, wantLines := legacyWordsLines(body)
	require.Equal(t, wantWords, resp.Words)
	require.Equal(t, wantLines, resp.Lines)
}

func TestDoBodyEmpty(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
	}))
	defer ts.Close()

	resp := doLocal(t, newLocalHTTPX(t), ts.URL)
	require.Empty(t, resp.Data)
	require.Empty(t, resp.RawData)
	require.Equal(t, 0, resp.Words)
	require.Equal(t, 0, resp.Lines)
}

// TestDoBodyGBKDecodeKeepsRawUndecoded ensures that when DecodeData actually
// transcodes the body, RawData still holds the original (undecoded) bytes while
// Data holds the decoded UTF-8 bytes.
func TestDoBodyGBKDecodeKeepsRawUndecoded(t *testing.T) {
	utf8Body := "<html><head></head><body>你好世界 测试</body></html>"
	gbkBody, _, err := transform.Bytes(simplifiedchinese.GBK.NewEncoder(), []byte(utf8Body))
	require.NoError(t, err)
	require.NotEqual(t, []byte(utf8Body), gbkBody, "precondition: gbk bytes differ from utf8")

	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=gbk")
		_, _ = w.Write(gbkBody)
	}))
	defer ts.Close()

	resp := doLocal(t, newLocalHTTPX(t), ts.URL)

	require.Equal(t, gbkBody, resp.RawData, "RawData must hold the original undecoded bytes")
	require.Equal(t, []byte(utf8Body), resp.Data, "Data must hold the decoded UTF-8 bytes")
}

// TestDoBodyNoDecodeSharesBacking documents the memory optimization: on the
// no-decode hot path RawData and Data share the same backing array (no extra
// full-body copy is made).
func TestDoBodyNoDecodeSharesBacking(t *testing.T) {
	body := []byte("shared backing array body")
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/plain")
		_, _ = w.Write(body)
	}))
	defer ts.Close()

	resp := doLocal(t, newLocalHTTPX(t), ts.URL)

	require.NotEmpty(t, resp.Data)
	require.NotEmpty(t, resp.RawData)
	require.Equal(t, resp.Data, resp.RawData)
	require.Same(t, &resp.Data[0], &resp.RawData[0],
		"RawData and Data should share the backing array on the no-decode path")
}

// TestWordsLinesEquivalence is the core guard for the refactor: the byte-based
// counting used on the hot path must be identical to the previous
// strings.Split-based counting for a wide range of inputs and edge cases.
func TestWordsLinesEquivalence(t *testing.T) {
	cases := []string{
		"",
		"a",
		"a b c",
		"   ",                        // only spaces
		"a  b",                       // consecutive spaces
		"line1\nline2\nline3",        // multiple lines
		"\n\n\n",                     // only newlines
		"  leading and trailing  ",   // surrounding whitespace
		"\n  mixed \t whitespace \n", // tabs/newlines around
		"trailing newline\n",
		"word",
		"tab\tseparated values",
		"unicode \u00a0 nbsp space",
		"emoji 😀 and spaces ",
	}

	for _, c := range cases {
		body := []byte(c)
		wantWords, wantLines := legacyWordsLines(body)

		var gotWords, gotLines int
		if len(body) > 0 {
			gotWords = bytes.Count(body, []byte{' '}) + 1
			gotLines = bytes.Count(bytes.TrimSpace(body), []byte{'\n'}) + 1
		}

		require.Equalf(t, wantWords, gotWords, "words mismatch for %q", c)
		require.Equalf(t, wantLines, gotLines, "lines mismatch for %q", c)
	}
}

// TestBodyMetricsCountingDoesNotAllocate locks in the optimization: the
// byte-based word/line counting used on the hot path must not allocate (the
// previous string(respbody) + strings.Split approach allocated O(len(body))).
// If someone reintroduces a full-body string copy or Split-based counting, this
// test fails.
func TestBodyMetricsCountingDoesNotAllocate(t *testing.T) {
	body := bytes.Repeat([]byte("lorem ipsum dolor sit amet\n"), 40000) // ~1MB
	var words, lines int

	allocs := testing.AllocsPerRun(50, func() {
		// identical expressions to the hot path in Do()
		words = bytes.Count(body, []byte{' '}) + 1
		lines = bytes.Count(bytes.TrimSpace(body), []byte{'\n'}) + 1
	})

	require.NotZero(t, words)
	require.NotZero(t, lines)
	require.Zerof(t, allocs, "word/line counting must not allocate, got %v allocs/op", allocs)
}

// TestDoTruncatedBodyIsNotAFailure guards against the regression where capping
// the body before dumping the response made the dump fail with
// "ContentLength=x with Body length y", turning a valid response into a failed
// one (issue #2641).
func TestDoTruncatedBodyIsNotAFailure(t *testing.T) {
	body := bytes.Repeat([]byte("A"), 4096)
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/pdf")
		w.Header().Set("Content-Length", strconv.Itoa(len(body)))
		_, _ = w.Write(body)
	}))
	defer ts.Close()

	const readSize = 10
	options := DefaultOptions
	options.CdnCheck = "false"
	options.Timeout = 5 * time.Second
	options.RetryMax = 0
	options.MaxResponseBodySizeToRead = readSize

	ht, err := New(&options)
	require.NoError(t, err)

	resp := doLocal(t, ht, ts.URL)

	require.Equal(t, http.StatusOK, resp.StatusCode)
	require.Equal(t, len(body), resp.ContentLength, "advertised content length must be reported")
	require.Len(t, resp.Data, readSize, "body must be capped to the configured read size")
	require.Contains(t, resp.RawHeaders, "Content-Length: "+strconv.Itoa(len(body)))
}

package httpx

import (
	"bytes"
	"fmt"
	"io"
	"regexp"
	"strings"

	stringsutil "github.com/projectdiscovery/utils/strings"
	"golang.org/x/net/html"
	"slices"
)

var (
	cutset                  = "\n\t\v\f\r"
	reTitle                 = regexp.MustCompile(`(?im)<\s*title.*>(.*?)<\s*/\s*title>`)
	reContentType           = regexp.MustCompile(`(?is)<meta\b[^>]*?charset\s*=\s*["']?([^"'\s;>/]+)`)
	reGenerator             = regexp.MustCompile(`(?i)<meta\b[^>]*?name\s*=\s*["']generator["'][^>]*?content\s*=\s*["']([^"']+)["']|<meta\b[^>]*?content\s*=\s*["']([^"']+)["'][^>]*?name\s*=\s*["']generator["']`)
	supportedTitleMimeTypes = []string{
		"text/html",
		"application/xhtml+xml",
		"application/xml",
		"application/rss+xml",
		"application/atom+xml",
		"application/xhtml+xml",
		"application/vnd.wap.xhtml+xml",
	}
)

// ExtractTitle from a response
func ExtractTitle(r *Response) (title string) {
	// Try to parse the DOM
	titleDom, err := getTitleWithDom(r)
	// In case of error fallback to regex
	if err != nil {
		for _, match := range reTitle.FindAllString(r.Raw, -1) {
			title = match
			break
		}
	} else {
		title = renderNode(titleDom)
	}

	title = html.UnescapeString(trimTitleTags(title))

	// remove unwanted chars
	title = strings.TrimSpace(strings.Trim(title, cutset))
	title = stringsutil.ReplaceAll(title, "", "\n", "\t", "\v", "\f", "\r")

	return title
}

// ExtractGenerator extracts the content of <meta name="generator"> from a response.
func ExtractGenerator(r *Response) string {
	matches := reGenerator.FindSubmatch(r.Data)
	var raw []byte
	if len(matches) >= 3 {
		if len(matches[1]) > 0 {
			raw = matches[1]
		} else if len(matches[2]) > 0 {
			raw = matches[2]
		}
	}
	if len(raw) == 0 {
		return ""
	}
	// Postgres rejects NUL in TEXT, and one bad value rolls back the whole batch.
	value := strings.ReplaceAll(string(raw), "\x00", "")
	return strings.TrimSpace(html.UnescapeString(value))
}

func CanHaveTitleTag(mimeType string) bool {
	return slices.Contains(supportedTitleMimeTypes, strings.ToLower(strings.TrimSpace(mimeType)))
}

func getTitleWithDom(r *Response) (*html.Node, error) {
	var title *html.Node
	var crawler func(*html.Node)
	crawler = func(node *html.Node) {
		if node.Type == html.ElementNode && node.Data == "title" {
			title = node
			return
		}
		for child := node.FirstChild; child != nil && title == nil; child = child.NextSibling {
			crawler(child)
		}
	}
	htmlDoc, err := html.Parse(bytes.NewReader(r.Data))
	if err != nil {
		return nil, err
	}
	crawler(htmlDoc)
	if title != nil {
		return title, nil
	}
	return nil, fmt.Errorf("title not found")
}

func renderNode(n *html.Node) string {
	var buf bytes.Buffer
	w := io.Writer(&buf)
	html.Render(w, n) //nolint
	return buf.String()
}

func trimTitleTags(title string) string {
	titleBegin := strings.Index(title, ">")
	titleEnd := strings.Index(title, "</")
	if titleEnd < 0 || titleBegin < 0 || titleEnd <= titleBegin {
		return title
	}
	return title[titleBegin+1 : titleEnd]
}

package httpx

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/stretchr/testify/require"
)

func TestCanHaveTitleTag(t *testing.T) {
	tests := []struct {
		mimeType string
		expected bool
	}{
