package httpx

import (
	"fmt"

	"github.com/hbakhtiyor/strsim"
	retryablehttp "github.com/projectdiscovery/retryablehttp-go"
	"github.com/rs/xid"
)

const simMultiplier = 100

// IsVirtualHost checks if the target endpoint is a virtual host
func (h *HTTPX) IsVirtualHost(req *retryablehttp.Request, unsafeOptions UnsafeOptions) (bool, error) {
	httpresp1, err := h.Do(req, unsafeOptions)
	if err != nil {
		return false, err
	}

	// request a non-existing endpoint
	req.Host = fmt.Sprintf("%s.%s", xid.New().String(), req.Host)

	httpresp2, err := h.Do(req, unsafeOptions)
	if err != nil {
		return false, err
	}

	// Status Code
	if !h.Options.VHostIgnoreStatusCode && httpresp1.StatusCode != httpresp2.StatusCode {
		return true, nil
	}

	// Content - Bytes Length
	if !h.Options.VHostIgnoreContentLength && httpresp1.ContentLength != httpresp2.ContentLength {
		return true, nil
	}

	// Content - Number of words (space separated)
	if !h.Options.VHostIgnoreNumberOfWords && httpresp1.Words != httpresp2.Words {
		return true, nil
	}

	// Content - Number of lines (newline separated)
	if !h.Options.VHostIgnoreNumberOfLines && httpresp1.Lines != httpresp2.Lines {
		return true, nil
	}

	// Similarity Ratio - if similarity is under threshold we consider it a valid vHost
	if int(strsim.Compare(httpresp1.Raw, httpresp2.Raw)*simMultiplier) <= h.Options.VHostSimilarityRatio {
		return true, nil
	}

	return false, nil
}

package inputformats

import (
	"io"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/gologger"
	"github.com/seh-msft/burpxml"
)

// BurpFormat is a Burp Suite XML file parser
type BurpFormat struct{}

// NewBurpFormat creates a new Burp XML file parser
func NewBurpFormat() *BurpFormat {
	return &BurpFormat{}
}

var _ Format = &BurpFormat{}

// Name returns the name of the format
func (b *BurpFormat) Name() string {
	return "burp"
}

// Parse parses the Burp XML input and calls the provided callback
// function for each URL it discovers.
func (b *BurpFormat) Parse(input io.Reader, callback func(url string) bool) error {
	items, err := burpxml.Parse(input, true)
	if err != nil {
		return errors.Wrap(err, "could not parse burp xml")
	}

	for i, item := range items.Items {
		if item.Url == "" {
			gologger.Debug().Msgf("Skipping burp item %d: empty URL", i)
			continue
		}
		if !callback(item.Url) {
			break
		}
	}
	return nil
}

// TODO: This package should be abstracted out to projectdiscovery/utils
// so it can be shared between httpx, nuclei, and other tools.
package inputformats

import (
	"io"
	"strings"
)

// Format is an interface implemented by all input formats
type Format interface {
	// Name returns the name of the format
	Name() string
	// Parse parses the input and calls the provided callback
	// function for each URL it discovers.
	Parse(input io.Reader, callback func(url string) bool) error
}

// Supported formats
var formats = []Format{
	NewBurpFormat(),
}

// GetFormat returns the format by name
func GetFormat(name string) Format {
	for _, f := range formats {
		if strings.EqualFold(f.Name(), name) {
			return f
		}
	}
	return nil
}

// SupportedFormats returns a comma-separated list of supported format names
func SupportedFormats() string {
	var names []string
	for _, f := range formats {
		names = append(names, f.Name())
	}
	return strings.Join(names, ", ")
}

