// recorder is a database/sql connector that keeps every statement it gets, so
// the SQL writers can be checked without a running database.
type recorder struct {
	queries []string
	args    int // values passed to the last Exec
}

func (r *recorder) Connect(context.Context) (driver.Conn, error) { return &recConn{r}, nil }
func (r *recorder) Driver() driver.Driver                        { return nil }

type recConn struct{ r *recorder }

func (c *recConn) Prepare(q string) (driver.Stmt, error) {
	c.r.queries = append(c.r.queries, q)
	return recStmt{c.r}, nil
}
func (c *recConn) Close() error                             { return nil }
func (c *recConn) Begin() (driver.Tx, error)                { return recTx{}, nil }
func (c *recConn) CheckNamedValue(*driver.NamedValue) error { return nil }

type recStmt struct{ r *recorder }

func (recStmt) Close() error  { return nil }
func (recStmt) NumInput() int { return -1 }
func (s recStmt) Exec(args []driver.Value) (driver.Result, error) {
	s.r.args = len(args)
	return driver.RowsAffected(1), nil
}

// Query answers MySQL's information_schema column check with "exists".
func (recStmt) Query([]driver.Value) (driver.Rows, error) { return &oneRow{}, nil }

type recTx struct{}

func (recTx) Commit() error   { return nil }
func (recTx) Rollback() error { return nil }

type oneRow struct{ done bool }

func (*oneRow) Columns() []string { return []string{"count"} }
func (*oneRow) Close() error      { return nil }
func (o *oneRow) Next(dest []driver.Value) error {
	if o.done {
		return io.EOF
	}
	o.done = true
	dest[0] = int64(1)
	return nil
}

// columnFor maps a Result JSON key to its column where the names differ.
var columnFor = map[string]string{"time": "response_time"}

var insertColumns = regexp.MustCompile(`(?s)INSERT INTO \S+ \((.*?)\) VALUES`)

// Every Result field in the JSON output must be stored by the SQL writers.
// New fields were silently dropped from the database before (#2487).
func TestSQLWritersStoreEveryResultField(t *testing.T) {
	var want []string
	rt := reflect.TypeOf(runner.Result{})
	for i := 0; i < rt.NumField(); i++ {
		key := strings.Split(rt.Field(i).Tag.Get("json"), ",")[0]
		if key == "" || key == "-" {
			continue
		}
		if col, ok := columnFor[key]; ok {
			key = col
		}
		want = append(want, key)
	}

	writers := map[string]func(*Config, *sql.DB) Database{
		"postgres": func(c *Config, db *sql.DB) Database { return &postgresDatabase{cfg: c, db: db} },
		"mysql":    func(c *Config, db *sql.DB) Database { return &mysqlDatabase{cfg: c, db: db} },
	}
	for name, newWriter := range writers {
		t.Run(name, func(t *testing.T) {
			rec := &recorder{}
			db := sql.OpenDB(rec)
			t.Cleanup(func() { _ = db.Close() })
			w := newWriter(&Config{TableName: "results"}, db)
			ctx := context.Background()
			require.NoError(t, w.EnsureSchema(ctx))
			schema := strings.Join(rec.queries, "\n")
			require.NoError(t, w.InsertBatch(ctx, []runner.Result{{}}))

			m := insertColumns.FindStringSubmatch(rec.queries[len(rec.queries)-1])
			require.NotNil(t, m, "insert statement not found")
			var got []string
			for _, col := range strings.Split(m[1], ",") {
				got = append(got, strings.Trim(strings.TrimSpace(col), "`"))
			}
			require.Equal(t, len(got), rec.args, "insert columns and values differ")
			for _, col := range want {
				require.Contains(t, got, col, "column missing from insert")
				require.Regexp(t, `(?m)^\s*`+"`?"+col+"`?"+`\s+\w`, schema, "column missing from schema")
			}
		})
	}
}

package db

import (
	"fmt"
	"os"
	"time"

	"gopkg.in/yaml.v3"
)

const (
	DefaultBatchSize     = 100
	DefaultFlushInterval = time.Minute
	DefaultTableName     = "results"
	DefaultDatabaseName  = "httpx"
	EnvConnectionString  = "HTTPX_DB_CONNECTION_STRING"
)

type Config struct {
	Type             DatabaseType  `yaml:"type"`
	ConnectionString string        `yaml:"connection-string"`
	DatabaseName     string        `yaml:"database-name"`
	TableName        string        `yaml:"table-name"`
	BatchSize        int           `yaml:"batch-size"`
	FlushInterval    time.Duration `yaml:"flush-interval"`
	OmitRaw          bool          `yaml:"omit-raw"`
}

func (c *Config) Validate() error {
	if !c.Type.IsValid() {
		return fmt.Errorf("invalid database type: %s (supported: %v)", c.Type, SupportedDatabases())
	}

	if c.ConnectionString == "" {
		return fmt.Errorf("connection string is required")
	}

	return nil
}

func (c *Config) ApplyDefaults() {
	if c.DatabaseName == "" {
		c.DatabaseName = DefaultDatabaseName
	}

	if c.TableName == "" {
		c.TableName = DefaultTableName
	}

	if c.BatchSize <= 0 {
		c.BatchSize = DefaultBatchSize
	}

	if c.FlushInterval <= 0 {
		c.FlushInterval = DefaultFlushInterval
	}
}

func LoadConfigFromFile(configPath string) (*Config, error) {
	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file: %w", err)
	}

	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("failed to parse config file: %w", err)
	}

	if cfg.ConnectionString == "" {
		cfg.ConnectionString = os.Getenv(EnvConnectionString)
	}

	cfg.ApplyDefaults()

	if err := cfg.Validate(); err != nil {
		return nil, err
	}

	return &cfg, nil
}

type Options struct {
	Enabled          bool
	ConfigFile       string
	Type             string
	ConnectionString string
	DatabaseName     string
	TableName        string
	BatchSize        int
	OmitRaw          bool
}

func (o *Options) ToConfig() (*Config, error) {
	cfg := &Config{
		Type:             DatabaseType(o.Type),
		ConnectionString: o.ConnectionString,
		DatabaseName:     o.DatabaseName,
		TableName:        o.TableName,
		BatchSize:        o.BatchSize,
		OmitRaw:          o.OmitRaw,
	}

	cfg.ApplyDefaults()

	if err := cfg.Validate(); err != nil {
		return nil, err
	}

	return cfg, nil
}

package db

import (
	"context"
	"fmt"

	"github.com/projectdiscovery/httpx/runner"
)

type DatabaseType string

const (
	MongoDB    DatabaseType = "mongodb"
	PostgreSQL DatabaseType = "postgres"
	MySQL      DatabaseType = "mysql"
)

func (d DatabaseType) String() string {
	return string(d)
}

func (d DatabaseType) IsValid() bool {
	switch d {
	case MongoDB, PostgreSQL, MySQL:
		return true
	default:
		return false
	}
}

type Database interface {
	Connect(ctx context.Context) error

	Close() error

	InsertBatch(ctx context.Context, results []runner.Result) error

	EnsureSchema(ctx context.Context) error

	Type() DatabaseType
}

type databaseFactory func(cfg *Config) (Database, error)

var registry = make(map[DatabaseType]databaseFactory)

func Register(dbType DatabaseType, factory databaseFactory) {
	registry[dbType] = factory
}

func NewDatabase(cfg *Config) (Database, error) {
	if cfg == nil {
		return nil, fmt.Errorf("database configuration is required")
	}

	if !cfg.Type.IsValid() {
		return nil, fmt.Errorf("unsupported database type: %s", cfg.Type)
	}

	factory, ok := registry[cfg.Type]
	if !ok {
		return nil, fmt.Errorf("database type %s is not registered", cfg.Type)
	}

	return factory(cfg)
}

func SupportedDatabases() []DatabaseType {
	return []DatabaseType{MongoDB, PostgreSQL, MySQL}
}

package db

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/projectdiscovery/httpx/runner"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

func init() {
	Register(MongoDB, newMongoDatabase)
}

type mongoDatabase struct {
	cfg        *Config
	client     *mongo.Client
	database   *mongo.Database
	collection *mongo.Collection
}

func newMongoDatabase(cfg *Config) (Database, error) {
	return &mongoDatabase{cfg: cfg}, nil
}

func (m *mongoDatabase) Connect(ctx context.Context) error {
	clientOpts := options.Client().
		ApplyURI(m.cfg.ConnectionString).
		SetConnectTimeout(10 * time.Second).
		SetServerSelectionTimeout(10 * time.Second)

	client, err := mongo.Connect(ctx, clientOpts)
	if err != nil {
		return fmt.Errorf("failed to connect to MongoDB: %w", err)
	}

	if err := client.Ping(ctx, nil); err != nil {
		return fmt.Errorf("failed to ping MongoDB: %w", err)
	}

	m.client = client
	m.database = client.Database(m.cfg.DatabaseName)
	m.collection = m.database.Collection(m.cfg.TableName)

	return nil
}

func (m *mongoDatabase) Close() error {
	if m.client != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		return m.client.Disconnect(ctx)
	}
	return nil
}

func (m *mongoDatabase) EnsureSchema(ctx context.Context) error {
	indexes := []mongo.IndexModel{
		{
			Keys: bson.D{{Key: "timestamp", Value: -1}},
		},
		{
			Keys: bson.D{{Key: "url", Value: 1}},
		},
		{
			Keys: bson.D{{Key: "host", Value: 1}},
		},
		{
			Keys: bson.D{{Key: "status_code", Value: 1}},
		},
		{
			Keys:    bson.D{{Key: "tech", Value: 1}},
			Options: options.Index().SetSparse(true),
		},
	}

	_, err := m.collection.Indexes().CreateMany(ctx, indexes)
	if err != nil {
		return fmt.Errorf("failed to create indexes: %w", err)
	}

	return nil
}

func (m *mongoDatabase) InsertBatch(ctx context.Context, results []runner.Result) error {
	if len(results) == 0 {
		return nil
	}

	documents := make([]interface{}, len(results))
	for i, r := range results {
		doc, err := m.resultToDocument(r)
		if err != nil {
			return fmt.Errorf("failed to convert result to document: %w", err)
		}
		documents[i] = doc
	}

	_, err := m.collection.InsertMany(ctx, documents)
	if err != nil {
		return fmt.Errorf("failed to insert batch: %w", err)
	}

	return nil
}

func (m *mongoDatabase) Type() DatabaseType {
	return MongoDB
}

func (m *mongoDatabase) resultToDocument(r runner.Result) (bson.M, error) {
	jsonBytes, err := json.Marshal(r)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal result to JSON: %w", err)
	}

	var doc bson.M
	if err := json.Unmarshal(jsonBytes, &doc); err != nil {
		return nil, fmt.Errorf("failed to unmarshal JSON to BSON: %w", err)
	}

	return doc, nil
}

package db

import (
	"context"
	"sync/atomic"
	"time"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/httpx/runner"
	"github.com/projectdiscovery/utils/batcher"
)

type Writer struct {
	db      Database
	cfg     *Config
	batcher *batcher.Batcher[runner.Result]
	counter atomic.Int64
	closed  atomic.Bool
	omitRaw bool
}

func NewWriter(ctx context.Context, cfg *Config) (*Writer, error) {
	db, err := NewDatabase(cfg)
	if err != nil {
		return nil, err
	}

	if err := db.Connect(ctx); err != nil {
		return nil, err
	}

	if err := db.EnsureSchema(ctx); err != nil {
		_ = db.Close()
		return nil, err
	}

	w := &Writer{
		db:      db,
		cfg:     cfg,
		omitRaw: cfg.OmitRaw,
	}

	w.batcher = batcher.New(
		batcher.WithMaxCapacity[runner.Result](cfg.BatchSize),
		batcher.WithFlushInterval[runner.Result](cfg.FlushInterval),
		batcher.WithFlushCallback(w.flush),
	)

	w.batcher.Run()

	gologger.Info().Msgf("Database output enabled: %s (%s/%s)", cfg.Type, cfg.DatabaseName, cfg.TableName)

	return w, nil
}

func (w *Writer) flush(batch []runner.Result) {
	if len(batch) == 0 {
		return
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := w.db.InsertBatch(ctx, batch); err != nil {
		gologger.Error().Msgf("Failed to insert batch to database: %v", err)
	} else {
		w.counter.Add(int64(len(batch)))
		gologger.Verbose().Msgf("Inserted %d results to database (total: %d)", len(batch), w.counter.Load())
	}
}

func (w *Writer) GetWriterCallback() runner.OnResultCallback {
	return func(r runner.Result) {
		if w.closed.Load() {
			return
		}

		if r.Err != nil {
			return
		}

		if w.omitRaw {
			r.Raw = ""
			r.Request = ""
			r.ResponseBody = ""
			r.RawHeaders = ""
		}

		w.batcher.Append(r)
	}
}

func (w *Writer) Close() {
	if !w.closed.CompareAndSwap(false, true) {
		return
	}

	w.batcher.Stop()
	w.batcher.WaitDone()

	if err := w.db.Close(); err != nil {
		gologger.Error().Msgf("Error closing database connection: %v", err)
	}

	gologger.Info().Msgf("Database writer closed. Total results stored: %d", w.counter.Load())
}

func (w *Writer) Stats() int64 {
	return w.counter.Load()
}

