package pdcp

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"sync/atomic"
	"time"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/httpx/runner"
	"github.com/projectdiscovery/retryablehttp-go"
	pdcpauth "github.com/projectdiscovery/utils/auth/pdcp"
	"github.com/projectdiscovery/utils/conversion"
	"github.com/projectdiscovery/utils/env"
	"github.com/projectdiscovery/utils/errkit" //
	unitutils "github.com/projectdiscovery/utils/unit"
	updateutils "github.com/projectdiscovery/utils/update"
	urlutil "github.com/projectdiscovery/utils/url"
)

const (
	uploadEndpoint = "/v1/assets"
	appendEndpoint = "/v1/assets/%s/contents"
	flushTimer     = time.Minute
	MaxChunkSize   = 4 * unitutils.Mega // 4 MB
	xidRe          = `^[a-z0-9]{20}$`
	teamIDHeader   = "X-Team-Id"
	NoneTeamID     = "none"
)

var (
	xidRegex = regexp.MustCompile(xidRe)
	// EnableeUpload if set to true enables the upload feature
	HideAutoSaveMsg   = env.GetEnvOrDefault("DISABLE_CLOUD_UPLOAD_WRN", false)
	EnableCloudUpload = env.GetEnvOrDefault("ENABLE_CLOUD_UPLOAD", false)
)

// UploadWriter is a writer that uploads its output to pdcp
// server to enable web dashboard and more
type UploadWriter struct {
	creds          *pdcpauth.PDCPCredentials
	uploadURL      *url.URL
	client         *retryablehttp.Client
	done           chan struct{}
	data           chan runner.Result
	assetGroupID   string
	assetGroupName string
	counter        atomic.Int32
	closed         atomic.Bool
	TeamID         string
}

// NewUploadWriterCallback creates a new upload writer callback
// which when enabled periodically uploads the results to pdcp assets dashboard
func NewUploadWriterCallback(ctx context.Context, creds *pdcpauth.PDCPCredentials) (*UploadWriter, error) {
	if creds == nil {
		return nil, fmt.Errorf("no credentials provided")
	}
	u := &UploadWriter{
		creds:  creds,
		done:   make(chan struct{}, 1),
		data:   make(chan runner.Result, 8), // default buffer size
		TeamID: "",
	}
	var err error
	tmp, err := urlutil.Parse(creds.Server)
	if err != nil {
		return nil, errkit.Wrap(err, "could not parse server url")
	}
	tmp.Path = uploadEndpoint
	tmp.Update()
	u.uploadURL = tmp.URL

	// create http client
	opts := retryablehttp.DefaultOptionsSingle
	opts.NoAdjustTimeout = true
	opts.Timeout = time.Duration(3) * time.Minute
	u.client = retryablehttp.NewClient(opts)
	// start auto commit
	// upload every 1 minute or when buffer is full
	go u.autoCommit(ctx)
	return u, nil
}

// GetWriterCallback returns the writer callback
func (u *UploadWriter) GetWriterCallback() runner.OnResultCallback {
	return func(r runner.Result) {
		if r.Err != nil {
			return
		}
		u.data <- r
	}
}

// SetAssetID sets the scan id for the upload writer
func (u *UploadWriter) SetAssetID(id string) {
	if !xidRegex.MatchString(id) {
		gologger.Warning().Msgf("invalid asset id provided (unknown xid format): %s", id)
	}
	u.assetGroupID = id
}

// SetAssetGroupName sets the scan name for the upload writer
func (u *UploadWriter) SetAssetGroupName(name string) {
	u.assetGroupName = name
}

// SetTeamID sets the team id for the upload writer
func (u *UploadWriter) SetTeamID(id string) {
	u.TeamID = id
}

func (u *UploadWriter) autoCommit(ctx context.Context) {
	// wait for context to be done
	defer func() {
		u.done <- struct{}{}
		close(u.done)
		// if no scanid is generated no results were uploaded
		if u.assetGroupID == "" {
			gologger.Verbose().Msgf("UI dashboard setup skipped, no results found to upload")
		} else {
			gologger.Info().Msgf("Found %v results, View found results in dashboard : %v", u.counter.Load(), getAssetsDashBoardURL(u.assetGroupID, u.TeamID))
		}
	}()
	// temporary buffer to store the results
	buff := &bytes.Buffer{}
	ticker := time.NewTicker(flushTimer)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			// flush before exit
			if buff.Len() > 0 {
				if err := u.uploadChunk(buff); err != nil {
					gologger.Error().Msgf("Failed to upload scan results on cloud: %v", err)
				}
			}
			return
		case <-ticker.C:
			// flush the buffer
			if buff.Len() > 0 {
				if err := u.uploadChunk(buff); err != nil {
					gologger.Error().Msgf("Failed to upload scan results on cloud: %v", err)
				}
			}
		case res, ok := <-u.data:
			if !ok {
				if buff.Len() > 0 {
					if err := u.uploadChunk(buff); err != nil {
						gologger.Error().Msgf("Failed to upload scan results on cloud: %v", err)
					}
				}
				return
			}
			if res.Err != nil {
				// skip we don't care
				continue
			}
			lineBytes, err := json.Marshal(res)
			if err != nil {
				gologger.Error().Msgf("Failed to marshal result: %v", err)
				continue
			}
			u.counter.Add(1)
			line := conversion.String(lineBytes)
			appendResultLine(buff, line, MaxChunkSize, func(b *bytes.Buffer) error {
				if err := u.uploadChunk(b); err != nil {
					gologger.Error().Msgf("Failed to upload asset results on cloud: %v", err)
					return err
				}
				return nil
			})
		}
	}
}

// uploadChunk uploads a chunk of data to the server
func (u *UploadWriter) uploadChunk(buff *bytes.Buffer) error {
	if err := u.upload(buff.Bytes()); err != nil {
		return errkit.Wrap(err, "could not upload chunk")
	}
	// if successful, reset the buffer
	buff.Reset()
	// log in verbose mode
	gologger.Warning().Msgf("Uploaded results chunk, you can view assets at %v", getAssetsDashBoardURL(u.assetGroupID, u.TeamID))
	return nil
}

func (u *UploadWriter) upload(data []byte) error {
	req, err := u.getRequest(data)
	if err != nil {
		return errkit.Wrap(err, "could not create upload request")
	}
	resp, err := u.client.Do(req)
	if err != nil {
		return errkit.Wrap(err, "could not upload results")
	}
	defer func() {
		_ = resp.Body.Close()
	}()
	bin, err := io.ReadAll(resp.Body)
	if err != nil {
		return errkit.Wrap(err, "could not get id from response")
	}
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("could not upload results got status code %v on %v", resp.StatusCode, resp.Request.URL.String())
	}
	var uploadResp uploadResponse
	if err := json.Unmarshal(bin, &uploadResp); err != nil {
		return errkit.Wrapf(err, "could not unmarshal response got %v", string(bin))
	}
	if uploadResp.ID != "" && u.assetGroupID == "" {
		u.assetGroupID = uploadResp.ID
	}
	return nil
}

// getRequest returns a new request for upload
// if scanID is not provided create new scan by uploading the data
// if scanID is provided append the data to existing scan
func (u *UploadWriter) getRequest(bin []byte) (*retryablehttp.Request, error) {
	var method, url string

	if u.assetGroupID == "" {
		u.uploadURL.Path = uploadEndpoint
		method = http.MethodPost
		url = u.uploadURL.String()
	} else {
		u.uploadURL.Path = fmt.Sprintf(appendEndpoint, u.assetGroupID)
		method = http.MethodPatch
		url = u.uploadURL.String()
	}
	req, err := retryablehttp.NewRequest(method, url, bytes.NewReader(bin))
	if err != nil {
		return nil, errkit.Wrap(err, "could not create cloud upload request")
	}
	// add pdtm meta params
	req.Params.Merge(updateutils.GetpdtmParams(runner.Version))
	// if it is upload endpoint also include name if it exists
	if u.assetGroupName != "" && req.Path == uploadEndpoint {
		req.Params.Add("name", u.assetGroupName)
	}
	req.Update()

	req.Header.Set(pdcpauth.ApiKeyHeaderName, u.creds.APIKey)
	if u.TeamID != "" {
		req.Header.Set(teamIDHeader, u.TeamID)
	}
	req.Header.Set("Content-Type", "application/octet-stream")
	req.Header.Set("Accept", "application/json")
	return req, nil
}

// appendResultLine writes line and its trailing newline to buff, flushing
// existing data first when the next write would exceed max. An empty buffer is
// never flushed, so a single oversized line is retained instead of dropped or
// uploaded as an empty chunk.
func appendResultLine(buff *bytes.Buffer, line string, max int, flush func(*bytes.Buffer) error) {
	if buff.Len() > 0 && buff.Len()+len(line)+len("\n") > max {
		_ = flush(buff)
	}
	buff.WriteString(line)
	buff.WriteString("\n")
}

// Close closes the upload writer
func (u *UploadWriter) Close() {
	if u.closed.CompareAndSwap(false, true) {
		close(u.data)
	}
	<-u.done
}

package pdcp

import (
	"bytes"
	"errors"
	"sync"
	"testing"
	"time"

	"github.com/projectdiscovery/httpx/runner"
	"github.com/stretchr/testify/require"
)

func TestAppendResultLine(t *testing.T) {
	t.Run("keeps lines under the limit without flushing", func(t *testing.T) {
		buff := &bytes.Buffer{}
		flushed := 0
		appendResultLine(buff, "ab", 10, func(*bytes.Buffer) error {
			flushed++
			return nil
		})
		appendResultLine(buff, "cd", 10, func(*bytes.Buffer) error {
			flushed++
			return nil
		})
		require.Equal(t, 0, flushed)
		require.Equal(t, "ab\ncd\n", buff.String())
	})

	t.Run("flushes existing data and keeps the overflowing line", func(t *testing.T) {
		buff := &bytes.Buffer{}
		flush := func(b *bytes.Buffer) error {
			require.Equal(t, "aaaa\n", b.String())
			b.Reset()
			return nil
		}
		appendResultLine(buff, "aaaa", 6, flush)
		appendResultLine(buff, "bbbb", 6, flush)
		require.Equal(t, "bbbb\n", buff.String())
	})

	t.Run("does not flush an empty buffer for an oversized line", func(t *testing.T) {
		buff := &bytes.Buffer{}
		flushed := 0
		appendResultLine(buff, "toolong", 4, func(*bytes.Buffer) error {
			flushed++
			return nil
		})
		require.Equal(t, 0, flushed)
		require.Equal(t, "toolong\n", buff.String())
	})

	t.Run("newline counts towards the limit", func(t *testing.T) {
		buff := &bytes.Buffer{}
		const max = 6
		flush := func(b *bytes.Buffer) error {
			b.Reset()
			return nil
		}
		// "abc\n" is 4 bytes, appending "de\n" would reach 7 without counting
		// the newline in the check.
		appendResultLine(buff, "abc", max, flush)
		appendResultLine(buff, "de", max, flush)
		require.LessOrEqual(t, buff.Len(), max)
		require.Equal(t, "de\n", buff.String())
	})

	t.Run("still appends the current line when flush fails", func(t *testing.T) {
		buff := bytes.NewBufferString("old\n")
		appendResultLine(buff, "new", 4, func(*bytes.Buffer) error {
			return errors.New("upload failed")
		})
		require.Equal(t, "old\nnew\n", buff.String())
	})
}

func TestUploadWriterCloseWaits(t *testing.T) {
	u := &UploadWriter{
		done: make(chan struct{}, 1),
		data: make(chan runner.Result, 8),
	}

	started := make(chan struct{})
	release := make(chan struct{})
	go func() {
		for range u.data {
		}
		close(started)
		<-release
		u.done <- struct{}{}
		close(u.done)
	}()

	firstDone := make(chan struct{})
	go func() {
		u.Close()
		close(firstDone)
	}()

	select {
	case <-started:
	case <-time.After(2 * time.Second):
		t.Fatal("Close did not close the data channel")
	}

	secondDone := make(chan struct{})
	go func() {
		u.Close()
		close(secondDone)
	}()

	select {
	case <-secondDone:
		t.Fatal("second Close returned before autoCommit finished")
	case <-time.After(50 * time.Millisecond):
	}

	close(release)

	var wg sync.WaitGroup
	wg.Add(2)
	go func() { defer wg.Done(); <-firstDone }()
	go func() { defer wg.Done(); <-secondDone }()
	done := make(chan struct{})
	go func() { wg.Wait(); close(done) }()
	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("Close hung")
	}
}

package testutils

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// RunHttpxAndGetResults returns a list of the results
func RunHttpxAndGetResults(url string, debug bool, extra ...string) ([]string, error) {
	cmd := exec.Command("bash", "-c")
	cmdLine := `echo "` + url + `" | ./httpx `
	cmdLine += strings.Join(extra, " ")
	if debug {
		cmdLine += " -debug"
		cmd.Stderr = os.Stderr
	} else {
		cmdLine += " -silent"
	}

	cmd.Args = append(cmd.Args, cmdLine)

	data, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	parts := []string{}
	items := strings.Split(strings.TrimSpace(string(data)), "\n")
	for _, i := range items {
		if i != "" {
			parts = append(parts, i)
		}
	}
	return parts, nil
}

// RunHttpxAndGetCombinedResults returns the results as a single string variable
func RunHttpxAndGetCombinedResults(url string, debug bool, extra ...string) (string, error) {
	cmd := exec.Command("bash", "-c")
	cmdLine := `echo "` + url + `" | ./httpx `
	cmdLine += strings.Join(extra, " ")
	if debug {
		cmdLine += " -debug"
	} else {
		cmdLine += " -silent"
	}

	cmd.Args = append(cmd.Args, cmdLine)
	data, err := cmd.CombinedOutput()
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// RunHttpxBinaryAndGetResults returns a list of the results
func RunHttpxBinaryAndGetResults(target string, httpxBinary string, debug bool, args []string) ([]string, error) {
	cmd := exec.Command("bash", "-c")
	cmdLine := fmt.Sprintf(`echo %s | %s `, target, httpxBinary)
	cmdLine += strings.Join(args, " ")
	if debug {
		cmdLine += " -debug"
		cmd.Stderr = os.Stderr
	} else {
		cmdLine += " -silent"
	}

	cmd.Args = append(cmd.Args, cmdLine)
	data, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	parts := []string{}
	items := strings.Split(strings.TrimSpace(string(data)), "\n")
	for _, i := range items {
		if i != "" {
			parts = append(parts, i)
		}
	}
	return parts, nil
}

