func sliceContains(s []string, v string) bool {
	for _, e := range s {
		if e == v {
			return true
		}
	}
	return false
}

func TestEnrichCPEVersionsNoTechnologies(t *testing.T) {
	matches := []CPEInfo{
		{Product: "next.js", Vendor: "vercel", CPE: "cpe:2.3:a:vercel:next.js:*:*:*:*:*:*:*:*"},
	}
	got := EnrichCPEVersions(matches, nil)
	if got[0].CPE != matches[0].CPE {
		t.Fatalf("with no technologies CPE should be unchanged, got %q", got[0].CPE)
	}
	// the early-return path must still return a copy: mutating the result
	// must not reach back into the caller's input slice.
	got[0].CPE = "mutated"
	if matches[0].CPE == "mutated" {
		t.Fatalf("early-return aliased the input slice; want a copy")
	}
}

package runner

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// -csp-probe probes the domains of the Content-Security-Policy, so it must
// have them extracted without -efqdn, which also adds the domains of the body.
func TestCSPProbeExtractsCSPDomains(t *testing.T) {
	r, err := New(&Options{CSPProbe: true})
	require.NoError(t, err)
	defer r.Close()
	require.True(t, r.hp.Options.ExtractCSP)
	require.False(t, r.hp.Options.ExtractFqdn)
}

// Every input with a CSP gets its CSP domains probed, not only the first one,
// even though the probes of the first one turn -csp-probe off for themselves.
func TestCSPProbeProbesCSPDomainsOfEveryTarget(t *testing.T) {
	cspServer := func(domain string) string {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			w.Header().Set("Content-Security-Policy", "default-src 'self' https://cdn."+domain)
		}))
		t.Cleanup(srv.Close)
		return strings.TrimPrefix(srv.URL, "http://")
	}

	options := &Options{
		Threads:         5,
		RateLimit:       100,
		Retries:         0,
		Timeout:         2,
		Methods:         http.MethodGet,
		Delay:           -1,
		CSPProbe:        true,
		InputTargetHost: []string{cspServer("csp-one.invalid"), cspServer("csp-two.invalid")},
	}

	r, err := New(options)
	require.NoError(t, err)
	defer r.Close()
	r.RunEnumeration()

	for _, domain := range []string{"csp-one.invalid", "cdn.csp-one.invalid", "csp-two.invalid", "cdn.csp-two.invalid"} {
		require.True(t, r.seen(domain), "CSP domain %s was not probed", domain)
	}
}

package runner

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"

	"github.com/projectdiscovery/httpx/common/customheader"
	"github.com/projectdiscovery/httpx/common/stringz"
	urlutil "github.com/projectdiscovery/utils/url"
	"github.com/stretchr/testify/require"
)

// testFaviconGIF is a 1x1 GIF, which is enough for content type sniffing.
var testFaviconGIF = []byte("GIF89a\x01\x00\x01\x00\x80\x00\x00\x00\x00\x00\xff\xff\xff" +
	"!\xf9\x04\x01\x00\x00\x00\x00,\x00\x00\x00\x00\x01\x00\x01\x00\x00\x02\x02D\x01\x00;")

// An absolute favicon href that can't be fetched must not be retried as a
// path on the target ("/http://...").
func TestFaviconAbsoluteHrefIsNotRetriedAsRootPath(t *testing.T) {
	var (
		mu    sync.Mutex
		paths []string
	)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		mu.Lock()
		paths = append(paths, req.URL.Path)
		mu.Unlock()
		_, _ = w.Write([]byte(`<html><head><link rel="icon" href="http://127.0.0.1:1/icon.png"></head></html>`))
	}))
	defer srv.Close()

	options := &Options{
		Threads:   1,
		RateLimit: 10,
		Retries:   0,
		Timeout:   5,
		Methods:   http.MethodGet,
		Delay:     -1,
		Favicon:   true,
		// The CLI sets these; with 0 no body is read and no <link> is seen.
		MaxResponseBodySizeToRead: 1 << 20,
		MaxResponseBodySizeToSave: 1 << 20,
		OnResult:                  func(Result) {},
		InputTargetHost:           []string{srv.URL},
	}
	r, err := New(options)
	require.NoError(t, err)
	defer r.Close()
	r.RunEnumeration()

	mu.Lock()
	defer mu.Unlock()
	require.NotEmpty(t, paths)
	for _, p := range paths {
		require.False(t, strings.HasPrefix(p, "/http"), "unexpected request to %q", p)
	}
}

// A Host header set with -H selects the virtual host the target serves: the
// favicon must be fetched with that same Host, or the server returns the
// default host's icon (or none at all).
func TestFaviconKeepsCustomHostHeader(t *testing.T) {
	const vhost = "vhost.test"

	var (
		mu        sync.Mutex
		iconHosts []string
	)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		switch req.URL.Path {
		case "/":
			w.Header().Set("Content-Type", "text/html")
			_, _ = w.Write([]byte(`<html><head><title>vhost</title></head><body>vhost</body></html>`))
		case "/favicon.ico":
			mu.Lock()
			iconHosts = append(iconHosts, req.Host)
			mu.Unlock()
			if req.Host != vhost {
				http.NotFound(w, req)
				return
			}
			w.Header().Set("Content-Type", "image/x-icon")
			_, _ = w.Write(testFaviconGIF)
		default:
			http.NotFound(w, req)
		}
	}))
	defer srv.Close()

	var results []Result
	options := &Options{
		Threads:   1,
		RateLimit: 10,
		Retries:   0,
		Timeout:   5,
		Methods:   http.MethodGet,
		Delay:     -1,
		Favicon:   true,
		// The CLI sets these; with 0 no body is read and no icon is found.
		MaxResponseBodySizeToRead: 1 << 20,
		MaxResponseBodySizeToSave: 1 << 20,
		CustomHeaders:             customheader.CustomHeaders{"Host: " + vhost},
		OnResult:                  func(result Result) { results = append(results, result) },
		InputTargetHost:           []string{srv.URL},
	}
	r, err := New(options)
	require.NoError(t, err)
	defer r.Close()
	r.RunEnumeration()

	mu.Lock()
	hosts := append([]string(nil), iconHosts...)
	mu.Unlock()
	require.NotEmpty(t, hosts, "the favicon was never requested")
	for _, host := range hosts {
		require.Equal(t, vhost, host, "favicon request used the wrong Host header")
	}

	wantMMH3, wantMD5, err := stringz.FaviconHash(testFaviconGIF)
	require.NoError(t, err)
	require.Len(t, results, 1)
	require.Equal(t, fmt.Sprintf("%d", wantMMH3), results[0].FavIconMMH3)
	require.Equal(t, wantMD5, results[0].FavIconMD5)
}

func TestFaviconRequestHost(t *testing.T) {
	for _, tc := range []struct {
		name            string
		explicitHost    string
		requestHostname string
		resolvedURL     string
		want            string
	}{
		{
			name:            "virtual host on the target",
			explicitHost:    "vhost.test",
			requestHostname: "127.0.0.1",
			resolvedURL:     "http://127.0.0.1:8080/favicon.ico",
			want:            "vhost.test",
		},
		{
			name:            "virtual host and icon on its own name",
			explicitHost:    "vhost.test",
			requestHostname: "127.0.0.1",
			resolvedURL:     "http://vhost.test/favicon.ico",
			want:            "vhost.test",
		},
		{
			name:            "virtual host and redirect target",
			explicitHost:    "hackerone.com",
			requestHostname: "hackerone.com",
			resolvedURL:     "https://www.hackerone.com/favicon.ico",
			want:            "www.hackerone.com",
		},
		{
			name:            "no virtual host and icon on a CDN",
			requestHostname: "example.com",
			resolvedURL:     "https://cdn.example.net/icon.png",
			want:            "cdn.example.net",
		},
		{
			name:            "no virtual host and icon on the target",
			requestHostname: "127.0.0.1",
			resolvedURL:     "http://127.0.0.1:8080/favicon.ico",
			want:            "127.0.0.1:8080",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			resolvedURL, err := urlutil.Parse(tc.resolvedURL)
			require.NoError(t, err)
			require.Equal(t, tc.want, faviconRequestHost(tc.explicitHost, tc.requestHostname, resolvedURL))
		})
	}
}

package runner

import (
	"fmt"
	"strings"
	"time"
)

var (
	greaterThan      = ">"
	lessThan         = "<"
	equal            = "="
	greaterThanEq    = ">="
	lessThanEq       = "<="
	notEq            = "!="
	compareOperators = []string{greaterThanEq, lessThanEq, equal, lessThan, greaterThan, notEq}
)

type FilterOperator struct {
	flag string
}

// Parse the given value into operator and value pair
func (f FilterOperator) Parse(flagValue string) (string, time.Duration, error) {
	var (
		operator string
		value    time.Duration
		err      error
	)
	for _, op := range compareOperators {
		if strings.Contains(flagValue, op) {
			splittedFlagValue := strings.SplitAfter(flagValue, op)
			operator = strings.Trim(splittedFlagValue[0], " ")
			timeVal := strings.Trim(splittedFlagValue[1], " ")
			value, err = time.ParseDuration(timeVal)
			if err != nil && strings.Contains(err.Error(), "missing unit") {
				// A bare number is read as seconds. This retry used to drop its
				// error, so a number too large to hold as a duration left value
				// at zero and reported nothing, and the filter then matched
				// every host instead of rejecting the flag.
				value, err = time.ParseDuration(fmt.Sprintf("%ss", timeVal))
				if err != nil {
					return operator, value, fmt.Errorf("invalid value provided for %s", f.flag)
				}
			} else if err != nil {
				return operator, value, fmt.Errorf("invalid value provided for %s", f.flag)
			}
			break
		}
	}
	if operator == "" {
		return operator, value, fmt.Errorf("invalid operator provided for %s, valid operators are %s", f.flag, strings.Join(compareOperators, ","))
	}
	return operator, value, nil
}

package runner

import (
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestFilterOperatorParse(t *testing.T) {
	f := FilterOperator{flag: "-mrt, -match-response-time"}

	t.Run("valid", func(t *testing.T) {
		for _, tc := range []struct {
			in       string
			operator string
			value    time.Duration
		}{
			{in: "<1s", operator: "<", value: time.Second},
			{in: ">1s", operator: ">", value: time.Second},
			{in: "=1s", operator: "=", value: time.Second},
			{in: "<=1s", operator: "<=", value: time.Second},
			{in: ">=1s", operator: ">=", value: time.Second},
			{in: "!=1s", operator: "!=", value: time.Second},
			{in: "<100ms", operator: "<", value: 100 * time.Millisecond},
			// A bare number is read as seconds.
			{in: ">=5", operator: ">=", value: 5 * time.Second},
			// Surrounding spaces are trimmed.
			{in: ">= 5s ", operator: ">=", value: 5 * time.Second},
		} {
			t.Run(tc.in, func(t *testing.T) {
				operator, value, err := f.Parse(tc.in)
				require.NoError(t, err)
				require.Equal(t, tc.operator, operator)
				require.Equal(t, tc.value, value)
			})
		}
	})

	t.Run("rejected", func(t *testing.T) {
		for _, in := range []string{
			// No operator at all.
			"1s",
			"",
			// An operator with nothing after it.
			">=",
			// Not a number and not a duration.
			">=abc",
			// A bare number too large to hold as a duration once seconds are
			// added. This used to come back as 0 with no error, which turned
			// -mrt into a filter that matched every host.
			">=10000000000",
			">=99999999999999999999",
		} {
			t.Run(in, func(t *testing.T) {
				_, value, err := f.Parse(in)
				require.Error(t, err, "expected %q to be rejected", in)
				require.Zero(t, value)
			})
		}
	})
}

