import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/projectdiscovery/httpx/common/stringz"
	sliceutil "github.com/projectdiscovery/utils/slice"
	"github.com/stretchr/testify/require"
)

func TestWellKnownRecipes(t *testing.T) {
	for _, recipe := range WellKnownRecipes() {
		t.Run(recipe.Name, func(t *testing.T) {
			matched := false
			for path, fixture := range wellKnownFixtures {
				if !recipeMatchesPath(recipe, path) {
					continue
				}
				result := resultFromWellKnownFixture(path, fixture)
				if recipeMatches(recipe, result) {
					matched = true
					break
				}
			}
			require.True(t, matched, "recipe %q should match at least one fixture", recipe.Name)
		})
	}
}

func TestWellKnownRecipeSecurityTxtRejectsSoft404(t *testing.T) {
	recipe := WellKnownRecipes()[0]
	result := resultFromWellKnownFixture("/.well-known/security.txt", soft404Fixture)
	require.False(t, recipeMatches(recipe, result), "security.txt recipe should not match HTML soft-404 pages")
}

func TestWellKnownRecipeSecurityTxtRejectsMissingContact(t *testing.T) {
	recipe := WellKnownRecipes()[0]
	result := resultFromWellKnownFixture("/.well-known/security.txt", wellKnownFixture{
		statusCode:  http.StatusOK,
		contentType: "text/plain",
		body:        "Preferred-Languages: en\n",
	})
	require.False(t, recipeMatches(recipe, result), "security.txt recipe should require a Contact field")
}

func TestWellKnownRecipeAdsTxtRejectsInvalidBody(t *testing.T) {
	recipe := WellKnownRecipes()[4]
	result := resultFromWellKnownFixture("/ads.txt", wellKnownFixture{
		statusCode:  http.StatusOK,
		contentType: "text/plain",
		body:        "example.com, DIRECT\n",
	})
	require.False(t, recipeMatches(recipe, result), "ads.txt recipe should require an authorized digital seller entry")
}

func TestWellKnownRecipesHTTPProbe(t *testing.T) {
	ts := newWellKnownTestServer(t)
	defer ts.Close()

	recipe := WellKnownRecipes()[len(WellKnownRecipes())-1]
	for _, path := range strings.Split(recipe.Paths, ",") {
		t.Run(path, func(t *testing.T) {
			resp, err := http.Get(ts.URL + path)
			require.NoError(t, err)
			defer func() { _ = resp.Body.Close() }()
			require.Equal(t, http.StatusOK, resp.StatusCode)
		})
	}
}

func recipeMatchesPath(recipe WellKnownRecipe, path string) bool {
	for _, recipePath := range strings.Split(recipe.Paths, ",") {
		if recipePath == path {
			return true
		}
	}
	return false
}

func recipeMatches(recipe WellKnownRecipe, result Result) bool {
	if recipe.MatchStatusCode != "" {
		codes, err := stringz.StringToSliceInt(recipe.MatchStatusCode)
		if err != nil || !sliceutil.Contains(codes, result.StatusCode) {
			return false
		}
	}
	if recipe.MatchCondition != "" && !evalDslExpr(result, recipe.MatchCondition) {
		return false
	}
	return true
}

func resultFromWellKnownFixture(path string, fixture wellKnownFixture) Result {
	url := "http://example.com" + path
	contentType := fixture.contentType
	if idx := strings.Index(contentType, ";"); idx >= 0 {
		contentType = strings.TrimSpace(contentType[:idx])
	}
	return Result{
		StatusCode:   fixture.statusCode,
		ContentType:  contentType,
		ResponseBody: fixture.body,
		URL:          url,
		str:          url,
	}
}

func newWellKnownTestServer(t *testing.T) *httptest.Server {
	t.Helper()
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fixture, ok := wellKnownFixtures[r.URL.Path]
		if !ok {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", fixture.contentType)
		w.WriteHeader(fixture.statusCode)
		_, _ = w.Write([]byte(fixture.body))
	}))
}

package runner

import (
	"bufio"
	"bytes"
	"regexp"
	"strings"

	awesomesearchqueries "github.com/projectdiscovery/awesome-search-queries"
)

type WordPressInfo struct {
	Plugins []string `json:"plugins,omitempty"`
	Themes  []string `json:"themes,omitempty"`
}

type WordPressDetector struct {
	knownPlugins map[string]struct{}
	knownThemes  map[string]struct{}
	pluginRegex  *regexp.Regexp
	themeRegex   *regexp.Regexp
}

func NewWordPressDetector() (*WordPressDetector, error) {
	detector := &WordPressDetector{
		knownPlugins: make(map[string]struct{}),
		knownThemes:  make(map[string]struct{}),
	}

	var err error

	detector.pluginRegex, err = regexp.Compile(`/wp-content/plugins/([a-zA-Z0-9_-]+)/`)
	if err != nil {
		return nil, err
	}

	detector.themeRegex, err = regexp.Compile(`/wp-content/themes/([a-zA-Z0-9_-]+)/`)
	if err != nil {
		return nil, err
	}

	pluginsData, err := awesomesearchqueries.GetWordPressPlugins()
	if err != nil {
		return nil, err
	}
	if err := detector.loadList(pluginsData, detector.knownPlugins); err != nil {
		return nil, err
	}

	themesData, err := awesomesearchqueries.GetWordPressThemes()
	if err != nil {
		return nil, err
	}
	if err := detector.loadList(themesData, detector.knownThemes); err != nil {
		return nil, err
	}

	return detector, nil
}

func (d *WordPressDetector) loadList(data []byte, target map[string]struct{}) error {
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			target[line] = struct{}{}
		}
	}
	return scanner.Err()
}

func (d *WordPressDetector) Detect(body string) *WordPressInfo {
	if body == "" {
		return nil
	}

	info := &WordPressInfo{}
	seenPlugins := make(map[string]struct{})
	seenThemes := make(map[string]struct{})

	if matches := d.pluginRegex.FindAllStringSubmatch(body, -1); len(matches) > 0 {
		for _, match := range matches {
			if len(match) > 1 {
				plugin := match[1]
				if _, seen := seenPlugins[plugin]; !seen {
					if _, known := d.knownPlugins[plugin]; known {
						info.Plugins = append(info.Plugins, plugin)
						seenPlugins[plugin] = struct{}{}
					}
				}
			}
		}
	}

	if matches := d.themeRegex.FindAllStringSubmatch(body, -1); len(matches) > 0 {
		for _, match := range matches {
			if len(match) > 1 {
				theme := match[1]
				if _, seen := seenThemes[theme]; !seen {
					if _, known := d.knownThemes[theme]; known {
						info.Themes = append(info.Themes, theme)
						seenThemes[theme] = struct{}{}
					}
				}
			}
		}
	}

	if len(info.Plugins) == 0 && len(info.Themes) == 0 {
		return nil
	}

	return info
}

func (w *WordPressInfo) HasData() bool {
	return w != nil && (len(w.Plugins) > 0 || len(w.Themes) > 0)
}

